'use strict';
// Chemical typesetting is local so formulas also work without an internet connection.
const formulaCache=new Map();
function normalizeChemical(s){const subs='₀₁₂₃₄₅₆₇₈₉',sups='⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻';return String(s).replace(/[₀-₉]/g,c=>subs.indexOf(c)).replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻]+/g,g=>'^'+[...g].map(c=>'0123456789+-'[sups.indexOf(c)]).join('')).replace(/[−–]/g,'-').trim();}
function chemicalTeX(value){let s=normalizeChemical(value).replace(/^((?:SO4|CO3|SO3|PO4))([23][+-])$/,'$1^$2');if(!/^[A-Za-z0-9()^+\-\s]+$/.test(s))return null;s=s.replace(/^([A-Z][a-z]?)(\d*)([+-])$/,(_,e,n,q)=>e+'^'+n+q);let charge='';s=s.replace(/\^(\d*[+-])$/,(_,q)=>{charge=q;return'';});if(!charge)s=s.replace(/([+-])$/,(_,q)=>{charge=q;return'';});let coeff='';s=s.replace(/^(\d+)\s*(?=[A-Z])/,(_,n)=>{coeff=n+'\\,';return'';});if(!/^(?:[A-Z][a-z]?\d*|\([A-Za-z0-9]+\)\d*)+$/.test(s))return null;return coeff+s.replace(/([A-Z][a-z]?|[()])|([0-9]+)/g,(_,a,n)=>a?'\\mathrm{'+a+'}':'_{'+n+'}')+(charge?'^{'+charge+'}':'');}
function mathHTML(tex){return katex.renderToString(tex,{throwOnError:false,strict:'ignore',output:'htmlAndMathml'});}
chem=function(value){const key=String(value),tex=chemicalTeX(key);if(!tex)return esc(key);if(!formulaCache.has(key))formulaCache.set(key,mathHTML(tex));return formulaCache.get(key);};
const commonFormulas=new Set(['HCl','NaCl','NaOH','KOH','CuO','MgO','NH3','H2O','H3O','OH','CO2','SO2','HNO3','H2SO4','H2CO3','KCl','Na','Mg','Ca','Al','Zn','Fe','Cu','Ag','O2','H2','Cl2','N2','F2']);
function richChemicalText(text){const protectedText=String(text).replace(/([A-Za-z0-9])-(?=[a-zäö])/g,'$1‐');return protectedText.replace(/(?<![\p{L}\p{N}_])(?:[A-Z][a-z]?(?:[0-9₀-₉]+)?|\([A-Za-z0-9₀-₉]+\)[0-9₀-₉]*)(?:[A-Z][a-z]?(?:[0-9₀-₉]+)?|\([A-Za-z0-9₀-₉]+\)[0-9₀-₉]*)*(?:\^[0-9]*[+−-]|[⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻]+|[+−-])?(?![\p{L}\p{N}_])/gu,token=>/[0-9₀-₉^⁺⁻+−-]/.test(token)||commonFormulas.has(normalizeChemical(token))?chem(token):esc(token));}
function typesetChemicalText(root=app){const walk=node=>{if(node.nodeType===1){if(node.namespaceURI==='http://www.w3.org/2000/svg'||['SVG','SELECT','OPTION','INPUT','TEXTAREA','SCRIPT','STYLE'].includes(node.tagName.toUpperCase())||node.classList?.contains('katex')||node.classList?.contains('formula-preview')||node.classList?.contains('tension-series'))return;for(const child of Array.from(node.childNodes))walk(child);}else if(node.nodeType===3&&/[A-Z]/.test(node.textContent)){const before=node.textContent,after=richChemicalText(before);if(after.includes('katex')){const span=document.createElement('span');span.innerHTML=after;node.replaceWith(span);}}};walk(root);}
let mathObserver;
if(window.MutationObserver){let pending=false;mathObserver=new window.MutationObserver(()=>{if(pending)return;pending=true;Promise.resolve().then(()=>{mathObserver.disconnect();typesetChemicalText();mathObserver.observe(app,{childList:true,subtree:true});pending=false;});});mathObserver.observe(app,{childList:true,subtree:true});}
const originalFields=fieldHTML;
fieldHTML=function(f){if(f.type==='select')return originalFields(f).replace(/(<option[^>]*>)([^<]*)(<\/option>)/g,(_,a,v,b)=>a+esc(unicodeChem(v))+b);return originalFields(f);};
function signedCharge(q){return (q>=0?'+':'')+q;}
function chargeSumHTML(cp,ap,cq,aq){return mathHTML(`${cp}\\cdot(${signedCharge(cq)})+${ap}\\cdot(${signedCharge(aq)})=${cp*cq+ap*aq}`);}
function dotPair(x,y,angle=0){const dx=Math.cos(angle)*5,dy=Math.sin(angle)*5;return `<circle cx="${x-dx}" cy="${y-dy}" r="3.4" class="electron"/><circle cx="${x+dx}" cy="${y+dy}" r="3.4" class="electron"/>`;}
function lewisSymbolSVG(symbol,x,y,n){let s=txt(x,y+9,symbol,31);for(let side=0;side<Math.min(4,n);side++){const a=-Math.PI/2+side*Math.PI/2,px=x+33*Math.cos(a),py=y+33*Math.sin(a);s+=n>side+4?dotPair(px,py,a+Math.PI/2):`<circle cx="${px}" cy="${py}" r="3.4" class="electron"/>`;}return s;}
function atomDiagram(x,y,symbol,shells,z=null){let s='';shells.forEach((n,k)=>{const r=30+k*24;s+=`<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="#aab2bd" stroke-width="1.4"/>`;for(const a of shellElectronPositions(n,k))s+=`<circle cx="${x+r*Math.cos(a)}" cy="${y+r*Math.sin(a)}" r="4.3" class="electron" data-shell="${k}"/>`;});s+=`<circle cx="${x}" cy="${y}" r="21" fill="#eef1f5"/>`+txt(x,y+5,z===null?symbol:z+' p',z===null?18:14);return s;}
atomSVG=function(symbol,shells,dots=0){return svgStart(540,310,'Kuorimalli ja pistemalli')+atomDiagram(165,145,symbol,shells)+txt(165,294,'Kuorimalli',17)+lewisSymbolSVG(symbol,420,150,dots)+txt(420,294,'Pistemalli',17)+'</svg>';};
ionCompareSVG=function(e,q){if(q===null)return svgStart(600,300,'Atomin kuorimalli')+atomDiagram(300,145,e.s,e.shells,e.z)+txt(300,280,e.s,26)+'</svg>';let s=svgStart(600,310,'Atomi ja oppilaan valinnoista muodostuva ioni');s+=txt(150,27,'Atomi',21)+txt(450,27,'Ioni',21)+atomDiagram(150,155,e.s,e.shells,e.z)+atomDiagram(450,155,e.s,ionShells(e,q),e.z)+txt(150,290,e.s,26)+txt(450,290,e.s,26)+line(275,155,325,155,'marker-end="url(#arrow)"');for(let j=0;j<Math.abs(q);j++){const from=q>0?248:342,to=q>0?342:248;s+=`<circle cy="${110+j*14}" cx="${to}" r="4.3" fill="#172033"><animate attributeName="cx" from="${from}" to="${to}" dur=".7s" fill="freeze"/></circle>`;}s+=txt(300,88,`${Math.abs(q)} e${q>0?'⁻ →':'⁻ ←'}`,16);return s+'</svg>';};
function ionNode(sy,q,x,y,r=28){let s=`<circle cx="${x}" cy="${y}" r="${r}" fill="${q>0?'#dce2e9':'#fff'}" stroke="#525d6c" stroke-width="1.7"/>`;s+=txt(x,y+6,sy,sy.length>3?16:20)+txt(x+r*.75,y-r*.76,chargeText(q),16);return s;}
saltSVG=function(t,cp,ap){if(cp+ap===0)return svgStart(560,270,'Ionien lukumääräsuhde')+txt(280,135,'Valitse ionien lukumäärät.',20)+'</svg>';const balanced=cp>0&&ap>0&&cp*t.cq+ap*t.aq===0,repeat=balanced?3:1,ions=[];for(let k=0;k<repeat;k++){const c=Array(cp).fill(true),a=Array(ap).fill(false);while(c.length||a.length){if(c.length)ions.push(c.pop());if(a.length)ions.push(a.pop());if(ap>cp&&a.length)ions.push(a.pop());}}const cols=Math.min(6,Math.max(3,Math.ceil(Math.sqrt(ions.length*1.6)))),rows=Math.ceil(ions.length/cols),w=560,h=Math.max(230,rows*63+72),gap=68,left=w/2-(cols-1)*gap/2;let s=svgStart(w,h,balanced?'Ionirakenne':'Valitut ionit')+txt(280,29,balanced?'Ionirakenne':'Valitut ionit',20);ions.forEach((cat,j)=>s+=ionNode(cat?t.cation:t.anion,cat?t.cq:t.aq,left+j%cols*gap,74+Math.floor(j/cols)*63,25));if(balanced){s+=`<path d="M38 55v${rows*63-20}M522 55v${rows*63-20}" stroke="#9aa4b1" stroke-dasharray="4 6"/>`+txt(280,h-12,'Rakenne jatkuu kaikkiin suuntiin.',16);}return s+'</svg>';};
let exampleIonStep=0;
function ionicExampleSVG(step=0){const t=ION_TASKS.find(x=>x.formula==='CaCl2');if(step===3)return naclCrystalSVG();if(step===2)return saltSVG(t,1,2);let s=svgStart(560,240,'Kalsiumkloridin muodostuminen');if(step===0){s+=lewisSymbolSVG('Ca',130,120,2)+lewisSymbolSVG('Cl',395,65,7)+lewisSymbolSVG('Cl',395,180,7);s+=line(175,92,340,62,'marker-end="url(#arrow)"')+line(175,145,340,178,'marker-end="url(#arrow)"');s+=txt(280,220,'Kalsium luovuttaa kummallekin klooriatomille elektronin.',14);}else{s+=ionNode('Ca',2,140,118,34)+ionNode('Cl',-1,355,70,34)+ionNode('Cl',-1,355,166,34)+txt(280,225,'Ionien lukumääräsuhde on 1 : 2.',17);}return s+'</svg>';}
moleculeSVG=function(m,bonds,lones,style='dots'){let s=svgStart(540,330,'Molekyylin elektroniparimalli');const scaleX=x=>20+x;for(const [i,[a,b]] of m.b.entries()){const p=m.a[a],q=m.a[b],dx=q[1]-p[1],dy=q[2]-p[2],len=Math.hypot(dx,dy),nx=-dy/len,ny=dx/len,n=bonds[i]||0;for(let j=0;j<n;j++){const shift=(j-(n-1)/2)*13;if(style==='lines')s+=line(scaleX(p[1])+dx/len*22+nx*shift,p[2]+dy/len*22+ny*shift,scaleX(q[1])-dx/len*22+nx*shift,q[2]-dy/len*22+ny*shift);else s+=dotPair(scaleX((p[1]+q[1])/2)+nx*shift,(p[2]+q[2])/2+ny*shift,Math.atan2(dy,dx)+Math.PI/2);}}m.a.forEach(([sy,x,y],i)=>{x=scaleX(x);s+=txt(x,y+10,sy,32)+txt(x+19,y+27,i+1,12);const used=m.b.filter(b=>b[0]===i||b[1]===i).map(b=>{const p=m.a[b[0]===i?b[1]:b[0]];return Math.atan2(p[2]-y,p[1]-(x-20));});const options=Array.from({length:16},(_,j)=>-Math.PI/2+j*Math.PI/8);const score=a=>used.length?Math.min(...used.map(u=>Math.abs(Math.atan2(Math.sin(a-u),Math.cos(a-u))))):Math.PI;options.sort((a,b)=>score(b)-score(a));const chosen=[];for(const a of options){if(chosen.every(b=>Math.abs(Math.atan2(Math.sin(a-b),Math.cos(a-b)))>1.1))chosen.push(a);if(chosen.length>=(lones[i]||0))break;}chosen.slice(0,lones[i]||0).forEach(a=>s+=dotPair(x+34*Math.cos(a),y+34*Math.sin(a),a+Math.PI/2));});return s+'</svg>';};
function waterParticle(x,y){return `<g><circle cx="${x}" cy="${y}" r="19" fill="#dce2e9" stroke="#535d69"/>${txt(x,y+6,'O',17)}<circle cx="${x-24}" cy="${y+19}" r="12" fill="#fff" stroke="#535d69"/>${txt(x-24,y+24,'H',12)}<circle cx="${x+24}" cy="${y+19}" r="12" fill="#fff" stroke="#535d69"/>${txt(x+24,y+24,'H',12)}</g>`;}
function neutralModelSVG(spectators=[['Na',1],['Cl',-1]],pairs=1){let s=svgStart(620,330,'Neutraloitumisen ionit ennen reaktiota ja reaktion jälkeen');s+=txt(145,29,'Ennen reaktiota',21)+txt(470,29,'Reaktion jälkeen',21)+line(295,165,325,165,'marker-end="url(#arrow)"');for(let i=0;i<pairs;i++){s+=ionNode('H3O',1,82,87+i*72,27)+ionNode('OH',-1,210,87+i*72,27);s+=waterParticle(410,81+i*80)+waterParticle(520,81+i*80);}spectators.forEach(([sy,q],j)=>{const x=75+j*75;s+=ionNode(sy,q,x,260,24)+ionNode(sy,q,385+j*75,260,24);});return s+'</svg>';}
function taskBank(){return ({1:ATOM_TASKS,2:ION_TASKS,3:MOLECULES,4:PH_THEORY,5:NEUTRAL_TASKS,6:MYSTERY_THEORY,7:METAL_TASKS,8:ELECTRO_TASKS})[page];}
progressHeader=function(bank,title){let idx=indices[page]||0;if(idx>=bank.length)idx=indices[page]=0;const completed=(done[page]||[]).filter(k=>String(k).startsWith('task-')).length;return pageHead(title)+`<div class="task-navigation"><label>Tehtävä <select id="task-selector">${bank.map((t,i)=>`<option value="${i}" ${i===idx?'selected':''}>${i+1}. ${esc((t.title||t.prompt||t.name||E[t.s]?.name||'Tehtävä').slice(0,65))}</option>`).join('')}</select></label><span>Ratkaistu ${completed}/${bank.length}</span></div>`;};
document.addEventListener('change',e=>{if(e.target.id==='task-selector'){indices[page]=+e.target.value;persist();training();}});
pageHead=function(title){if(!page)return `<div class="top"><h1>${esc(title)}</h1></div>`;return `<div class="top"><h1>${esc(title)}</h1></div><nav class="tabs section-tabs" aria-label="Treenin osat">${[['intro','Tutustu'],['quiz','Monivalinnat'],['train','Harjoittele'],['apply','Sovella'],...(page>=4?[['lab','Laboratorio']]:[])].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}">${t}</button>`).join('')}</nav>`;};
const INTRO_TEXT=[
['Alkuaineiden järjestys','<b>Järjestysluku</b> kertoo atomin ytimen protonien määrän. Alkuaineet on järjestetty kasvavan järjestysluvun mukaan.','<b>Jakso</b> on vaakarivi. Sen numero kertoo atomin elektronikuorten määrän.','<b>Pääryhmä</b> on pystysarake ryhmissä 1, 2 tai 13–18. Ryhmissä 1 ja 2 atomilla on yksi tai kaksi ulkoelektronia. Ryhmissä 13–18 niitä on kolmesta kahdeksaan. Heliumilla on kaksi.','<b>Kuorten täyttö:</b> Sisimmälle kuorelle tulee enintään kaksi elektronia. Ensimmäisten 20 alkuaineen atomeissa seuraavilla kuorilla on enintään kahdeksan elektronia. Piirrä toisesta kuoresta alkaen ensin neljä elektronia yksittäin ja täydennä sitten parit.','<b>Kuorimalli</b> näyttää kaikki elektronit. <b>Pistemalli</b> näyttää vain ulkoelektronit kemiallisen merkin ympärillä.'],
['Ionit ja ioniyhdisteet','<b>Ioni</b> on sähköisesti varautunut hiukkanen. Atomi muuttuu ioniksi luovuttamalla tai vastaanottamalla elektroneja. Ydin pysyy samana.','Elektroneja luovuttava atomi muodostaa <b>positiivisen ionin</b>. Elektroneja vastaanottava atomi muodostaa <b>negatiivisen ionin</b>.','<b>Ioniyhdisteessä</b> positiiviset ja negatiiviset ionit vetävät toisiaan puoleensa. Ne muodostavat kiderakenteen. Ionien varausten summa on nolla.'],
['Kovalenttinen sidos','<b>Kovalenttisessa sidoksessa</b> atomit jakavat yhden tai useamman elektroniparin. Yhteinen pari kuuluu kummankin atomin uloimmalle kuorelle.','<b>Pistemallissa</b> elektronit näkyvät pisteinä. Atomien välissä ovat yhteiset parit, atomien ympärillä vapaat parit.','Yksi <b>sidosviiva</b> tarkoittaa yhtä yhteistä elektroniparia. Kaksoissidoksessa pareja on kaksi ja kolmoissidoksessa kolme.'],
['Hapot, emäkset ja pH','<b>Hapan vesiliuos:</b> pH on alle 7. <b>Neutraali vesiliuos:</b> pH on 7. <b>Emäksinen vesiliuos:</b> pH on yli 7. Nämä rajat koskevat huoneenlämpöisiä liuoksia.','Happamassa liuoksessa oksoniumioneja H3O+ on enemmän kuin hydroksidi-ioneja OH-. Emäksisessä liuoksessa hydroksidi-ioneja on enemmän.','<b>Indikaattorin</b> väri riippuu pH:sta. <b>BTS</b> on happamassa keltainen, neutraalin lähellä vihertävä ja emäksisessä sininen. pH-mittari näyttää pH-luvun.'],
['Happo ja emäs reagoivat','<b>Neutraloitumisessa</b> happo ja emäs reagoivat keskenään. Suolahapon ja kaliumhydroksidin reaktiossa syntyy kaliumkloridia ja vettä.','Vesiliuoksessa oksonium- ja hydroksidi-ionit reagoivat. Kalium- ja kloridi-ionit jäävät liuokseen.','<b>Titrauksessa</b> emäsliuosta lisätään vähitellen happoliuokseen. Byretin hanalla voi annostella pieniä määriä. Lähellä ekvivalenttipistettä pH muuttuu jyrkästi.'],
['Aine tunnistetaan havaintojen avulla','Tutki näytteiden <b>pH:ta ja sähkönjohtavuutta</b>. Karbonaatin tunnistamisessa voi auttaa hapon lisääminen.','Valitse tutkimus, jonka havainto erottaa mahdolliset aineet toisistaan. Ota jokaiseen tutkimukseen uusi pieni näyte.','Neutraali pH ei yksin erota sokeri- ja suolaliuosta. Suolaliuos johtaa sähköä selvästi, mutta sokeriliuos vain heikosti.'],
['Metallit ja hapettuminen','<b>Hapettumisessa</b> hiukkanen luovuttaa elektroneja. <b>Pelkistymisessä</b> hiukkanen vastaanottaa elektroneja.','Epäjalompi metalli voi luovuttaa elektroneja jalomman metallin ioneille. Jalompaa metallia kertyy silloin epäjalomman metallin pinnalle.','Raudan ruostuminen tarvitsee tavallisissa oloissa vettä ja happea. Ehjä suojakerros tai sähköisessä yhteydessä oleva uhrimetalli voi suojata terästä.'],
['Sähkökemiallinen pari ja kuparipinnoitus','<b>Sähkökemiallisessa parissa</b> kemiallinen reaktio tuottaa sähköenergiaa. Tässä sähkökemiallisessa parissa molemmat metallit ovat samassa elektrolyyttiliuoksessa.','<b>Kuparipinnoitus</b> käyttää sähköenergiaa. Pinnoitettava esine on miinusnavassa. Sen pinnalla kupari-ionit vastaanottavat elektroneja ja muuttuvat kupariksi.']
];
let moleculeDisplay='dots';
renderIntro=function(){view='intro';const t=INTRO_TEXT[page-1];let example='';if(page===1)example='<p>Natriumin järjestysluku on 11. Neutraalissa atomissa on 11 protonia ja 11 elektronia. Kuorilla on 2, 8 ja 1 elektronia.</p><div class="visual scientific-model">'+atomSVG('Na',[2,8,1],1)+'</div>';else if(page===2)example='<p>Kalsium luovuttaa kaksi elektronia. Kumpikin klooriatomi vastaanottaa yhden. Muodostuvan yhdisteen kaava on '+chem('CaCl2')+'.</p><div class="example-steps">'+['Elektronit','Ionit','Ionisuhde','NaCl-kide'].map((x,i)=>`<button data-ion-example="${i}" class="${i===exampleIonStep?'active':''}">${i+1}. ${x}</button>`).join('')+'</div><div id="ion-example" class="visual">'+ionicExampleSVG(exampleIonStep)+'</div><div class="charge-equation">'+chargeSumHTML(1,2,2,-1)+'</div>';else if(page===3){const m=MOLECULES.find(x=>x.formula==='H2O');example='<p>Vedessä happiatomi jakaa yhden elektroniparin kummankin vetyatomin kanssa. Hapelle jää kaksi vapaata paria.</p><div class="visual scientific-model">'+moleculeSVG(m,[1,1],[2,0,0],'dots')+'</div><p>'+chem('H2O')+'</p>';}else if(page===4)example='<p>Ruokasuolaliuoksen pH on 7. Se on neutraali, vaikka siinä on liuenneita ioneja.</p>'+artImage('ph-paper');else if(page===5)example='<div class="equation">'+chem('H3O^+')+' + '+chem('OH^-')+' → 2 '+chem('H2O')+'</div><div class="visual">'+neutralModelSVG()+'</div>';else if(page===6)example='<p>Kaksi väritöntä näytettä ovat molemmat neutraaleja. Sähkönjohtavuuden avulla voidaan erottaa ruokasuola- ja sokeriliuos.</p>'+artImage('unknown-setup');else if(page===7)example='<p>Kun rauta pannaan kupari-ioneja sisältävään liuokseen, rautaa liukenee ioneiksi ja pinnalle kertyy kuparia.</p>'+artImage('displacement-setup');else example='<p>Molemmat metallilevyt ovat samassa elektrolyyttiliuoksessa.</p>'+artImage('cell-setup');app.innerHTML=pageHead(TITLES[page-1])+`<div class="split intro-layout"><section class="panel"><h2>${t[0]}</h2>${t.slice(1).map(x=>'<p>'+x+'</p>').join('')}</section><section class="panel intro-example"><h2>Esimerkki</h2>${example}<button class="primary" data-view="quiz">Monivalintoihin →</button></section></div>`;app.querySelectorAll('[data-ion-example]').forEach(b=>b.onclick=()=>{exampleIonStep=+b.dataset.ionExample;renderIntro();});typesetChemicalText();};
renderQuiz=function(){
 view='quiz';const bank=QUIZZES[page-1],solved=(done[page]||[]).filter(x=>String(x).startsWith('quiz-item-'));
 app.innerHTML=pageHead(TITLES[page-1])+`<div id="quiz-count" class="counter">Ratkaistu ${solved.length}/${bank.length}</div><div class="panel quiz-list">${bank.map(([q,options,correct],i)=>{const locked=solved.includes('quiz-item-'+i);return `<fieldset class="quiz-question ${locked?'quiz-locked':''}" data-question="${i}"><legend><strong class="question-number">${i+1}.</strong> ${richChemicalText(q)}</legend><div class="quiz-options">${options.map((o,j)=>`<label class="${locked&&j===correct?'correct-choice':''}"><input type="radio" name="quiz-${i}" data-answer="${j}" value="${j}" ${locked?'disabled':''} ${locked&&j===correct?'checked':''}><span>${richChemicalText(o)}</span></label>`).join('')}</div><p class="feedback ${locked?'good':''}" aria-live="polite">${locked?'Oikein.':''}</p></fieldset>`;}).join('')}</div><div class="actions"><button data-view="train">Harjoittele →</button></div>`;
 app.querySelectorAll('[data-question]').forEach(box=>box.querySelectorAll('[data-answer]').forEach(input=>input.onchange=()=>{if(!input.checked||input.disabled)return;const i=+box.dataset.question,correct=bank[i][2],out=box.querySelector('.feedback'),label=input.closest('label');if(+input.dataset.answer===correct){box.querySelectorAll('.wrong-choice').forEach(x=>x.classList.remove('wrong-choice'));label.classList.add('correct-choice');box.classList.add('quiz-locked');box.querySelectorAll('input').forEach(x=>x.disabled=true);out.textContent='Oikein.';out.className='feedback good';mark('quiz-item-'+i);const n=(done[page]||[]).filter(x=>String(x).startsWith('quiz-item-')).length;$('#quiz-count').textContent=`Ratkaistu ${n}/${bank.length}`;}else{label.classList.add('wrong-choice');out.textContent='Valitse uudelleen.';out.className='feedback bad';}}));
};
renderIons=function(){const bank=ION_TASKS,t=bank[indices[2]||0];let fields,explain,title,art,update;if(t.kind==='ion'){const e=E[t.s],q=e.charge;title=`Millainen ioni ${e.name}atomista muodostuu?`;fields=[selectF('direction','Atomi',q>0?'luovuttaa':'vastaanottaa',['luovuttaa','vastaanottaa']),F('transfer','Kuinka monta elektronia?',Math.abs(q),'number'),F('charge','Ionin varaus',chargeText(q)),F('formula','Ionin kemiallinen merkintä',ionFormula(e.s,q),'formula'),F('p','Protonien määrä ionissa',e.z,'number'),F('electrons','Elektronien määrä ionissa',e.z-q,'number'),F('outer','Ulkoelektronien määrä ionissa',ionShells(e,q).at(-1),'number')];fields[2].answer=[chargeText(q),q>0?'+'+q:String(q),Math.abs(q)+(q>0?'+':'-'),q===1?'+':q===-1?'-':chargeText(q)];art='<div id="ion-visual" class="visual scientific-model"></div>';explain=`${chem(ionFormula(e.s,q))} muodostuu, kun atomi ${q>0?'luovuttaa':'vastaanottaa'} ${Math.abs(q)} ${Math.abs(q)===1?'elektronin':'elektronia'}. Ionissa on ${e.z} protonia ja ${e.z-q} elektronia.`;update=()=>{const direction=$('#f-direction').value,raw=$('#f-transfer').value,n=Number(raw.replace(',','.')),valid=direction&&raw!==''&&Number.isInteger(n)&&n>=1&&n<=3,actual=valid?(direction==='luovuttaa'?n:-n):null;$('#ion-visual').innerHTML=ionCompareSVG(e,actual!==null&&e.z-actual<=20&&e.z-actual>0?actual:null);};}else{title='Mikä ioniyhdiste muodostuu?';fields=[F('cp','Positiivisten ionien lukumäärä',t.cp,'number'),F('ap','Negatiivisten ionien lukumäärä',t.ap,'number'),F('formula','Yhdisteen kaava',t.formula,'formula'),F('name','Yhdisteen nimi',t.name)];art=`<p>Positiivinen ioni: ${chem(ionFormula(t.cation,t.cq))}<br>Negatiivinen ioni: ${chem(ionFormula(t.anion,t.aq))}</p><div id="salt-visual" class="visual scientific-model"></div><div id="salt-charge" class="charge-equation"></div><p>Valitse pienimmät ionimäärät, joilla varausten summa on nolla.</p>`;explain=chargeSumHTML(t.cp,t.ap,t.cq,t.aq)+`<p>Kaava on ${chem(t.formula)} ja nimi ${t.name}.</p>`;update=()=>{const cp=numericValue('cp',0,6),ap=numericValue('ap',0,6);$('#salt-visual').innerHTML=saltSVG(t,cp,ap);$('#salt-charge').innerHTML=chargeSumHTML(cp,ap,t.cq,t.aq);};}app.innerHTML=progressHeader(bank,TITLES[1])+`<div class="split training-layout"><section class="panel"><h2>${title}</h2>${art}<details><summary>Ionien nimet</summary><p>Kloridi ${chem('Cl^-')}, fluoridi ${chem('F^-')}, oksidi ${chem('O^2-')}, nitraatti ${chem('NO3^-')} ja sulfaatti ${chem('SO4^2-')}.</p></details></section><section class="panel">${formHTML(fields)}</section></div>`;bindForm(fields,explain,()=>advance(bank,renderIons),update);typesetChemicalText();};
renderMolecules=function(){const bank=MOLECULES,m=bank[indices[3]||0],fields=[F('formula','Molekyylin kaava',m.formula,'formula'),F('name','Aineen nimi',m.name),...m.b.map(([a,b,n],i)=>F('bond'+i,`Yhteisiä pareja: atomit ${a+1} ja ${b+1}`,n,'number')),...m.a.flatMap(([sy],i)=>sy==='H'?[]:[F('lone'+i,`Vapaita pareja: atomi ${i+1} (${sy})`,m.a[i][3],'number')])];app.innerHTML=progressHeader(bank,TITLES[2])+`<div class="split training-layout"><section class="panel"><h2>Rakenna ${esc(m.name)}molekyylin pistemalli.</h2><div class="example-steps"><button data-mstyle="dots" class="${moleculeDisplay==='dots'?'active':''}">Pisteet</button><button data-mstyle="lines" class="${moleculeDisplay==='lines'?'active':''}">Sidosviivat</button></div><div id="molecule-visual" class="visual scientific-model"></div><div id="electron-total" class="live-text"></div><details><summary>Ulkoelektronit</summary><p>H: 1, C: 4, N: 5, O ja S: 6, F ja Cl: 7. Yhteinen pari näkyy kummankin atomin ympärillä. Vety täyttää kahden elektronin kuoren, muut tämän sarjan atomit kahdeksan elektronin kuoren.</p></details></section><section class="panel">${formHTML(fields)}</section></div>`;const update=()=>{const bonds=m.b.map((_,i)=>numericValue('bond'+i,0,3)),lones=m.a.map(([sy],i)=>sy==='H'?0:numericValue('lone'+i,0,3));$('#molecule-visual').innerHTML=moleculeSVG(m,bonds,lones,moleculeDisplay);$('#electron-total').textContent='Ulkoelektroneja mallissa: '+2*(bonds.reduce((a,b)=>a+b,0)+lones.reduce((a,b)=>a+b,0));};bindForm(fields,`Yhteiset ja vapaat parit sisältävät yhteensä ${m.a.reduce((n,[sy])=>n+({H:1,C:4,N:5,O:6,S:6,F:7,Cl:7}[sy]),0)} elektronia.`,()=>advance(bank,renderMolecules),update);app.querySelectorAll('[data-mstyle]').forEach(b=>b.onclick=()=>{moleculeDisplay=b.dataset.mstyle;app.querySelectorAll('[data-mstyle]').forEach(x=>x.classList.toggle('active',x===b));update();});};
const NAME_FORMULAS=[['suolahappo','HCl'],['typpihappo','HNO3'],['rikkihappo','H2SO4'],['hiilihappo','H2CO3'],['etikkahappo','CH3COOH'],['fosforihappo','H3PO4'],['natriumhydroksidi','NaOH'],['kaliumhydroksidi','KOH'],['kalsiumhydroksidi','Ca(OH)2'],['ammoniakki','NH3'],['oksoniumioni','H3O^+'],['hydroksidi-ioni','OH^-']];
