renderPH=function(){const bank=PH_THEORY,t=bank[indices[4]||0];if(t.kind==='names'){app.innerHTML=progressHeader(bank,TITLES[3])+`<section class="panel"><h2>${t.prompt}</h2><p>Täydennä puuttuva nimi tai kaava.</p>${formHTML(t.fields)}</section>`;const rows=(start,end)=>`<table class="table formula-table"><thead><tr><th>Nimi</th><th>Kaava</th></tr></thead><tbody>${NAME_FORMULAS.slice(start,end).map(([name,formula],j)=>{const i=start+j,f=t.fields[i],input=fieldHTML(f).replace(/^[\s\S]*?(<input[\s\S]*)<\/label>$/,'$1');return `<tr><td>${i%2?input:esc(name)}</td><td>${i%2?chem(formula):input}</td></tr>`;}).join('')}</tbody></table>`;$('#answer-form .fields').innerHTML='<div class="name-table-grid">'+rows(0,6)+rows(6,12)+'</div>';bindForm(t.fields,t.explain,()=>advance(bank,renderPH));}else{app.innerHTML=progressHeader(bank,TITLES[3])+`<div class="split training-layout"><section class="panel"><h2>${t.title}</h2><p>${esc(t.prompt)}</p>${artImage(t.art)}</section><section class="panel">${formHTML(t.fields)}</section></div>`;bindForm(t.fields,t.explain,()=>advance(bank,renderPH));}typesetChemicalText();};
function renderPHLaboratory(){view='lab';const sample=SAMPLES[phLabIndex],rows=phMeasurements[phLabIndex]||[],fields=[selectF('kind','Liuos on',sample.kind,['hapan','neutraali','emäksinen']),selectF('ion','Liuoksessa on enemmän',sample.kind==='hapan'?'oksoniumioneja':sample.kind==='emäksinen'?'hydroksidi-ioneja':'molempia yhtä paljon',['oksoniumioneja','hydroksidi-ioneja','molempia yhtä paljon']),F('formula','Liuenneen aineen kaava',sample.formula,'formula')];app.innerHTML=pageHead(TITLES[3])+`<div class="task-navigation"><label>Näyte <select id="ph-sample">${SAMPLES.map((s,i)=>`<option value="${i}" ${i===phLabIndex?'selected':''}>${i+1}. ${s.name}</option>`).join('')}</select></label><span>Happamuuden tutkiminen</span></div><div class="split lab-split"><section class="panel"><div id="ph-art" class="visual lab-stage">${phLabSVG(sample,phTool,rows.some(r=>r.tool===phTool))}</div><div class="actions">${[['meter','pH-mittari'],['paper','pH-paperi'],['btb','BTS'],['cabbage','Punakaali']].map(([k,name])=>`<button data-ph="${k}" class="${phTool===k?'active':''}">${name}</button>`).join('')}</div><div id="ph-observation" class="log">Valitse tutkimusväline.</div><details><summary>Indikaattorien värit</summary><p>BTS: happamassa keltainen, neutraalin lähellä vihertävä, emäksisessä sininen. Punakaali: happamassa punertava, neutraalin lähellä violetti ja emäksisessä sinivihreä tai vihertävä.</p></details></section><section class="panel"><h2>Havainnot</h2><div id="ph-results">${phResultTable(rows)}</div>${formHTML(fields)}</section></div>`;$('#ph-sample').onchange=e=>{phLabIndex=+e.target.value;renderPHLaboratory();};app.querySelectorAll('[data-ph]').forEach(b=>b.onclick=()=>{phTool=b.dataset.ph;const text=phTool==='meter'?'pH '+nfi(sample.ph):phTool==='paper'?'pH noin '+Math.round(sample.ph):phTool==='btb'?(sample.ph<6?'keltainen':sample.ph>7.6?'sininen':'vihertävä'):(sample.ph<3?'punertava':sample.ph<8?'violetti':sample.ph<11?'sinivihreä':'vihertävä');if(!phMeasurements[phLabIndex])phMeasurements[phLabIndex]=[];if(!phMeasurements[phLabIndex].some(r=>r.tool===phTool))phMeasurements[phLabIndex].push({tool:phTool,text,name:b.textContent});$('#ph-art').innerHTML=phLabSVG(sample,phTool,true);$('#ph-observation').textContent=b.textContent+': '+text;$('#ph-results').innerHTML=phResultTable(phMeasurements[phLabIndex]);app.querySelectorAll('[data-ph]').forEach(x=>x.classList.toggle('active',x===b));});bindForm(fields,'Päätelmäsi vastaa näytteen happamuutta.',()=>{phLabIndex=(phLabIndex+1)%SAMPLES.length;renderPHLaboratory();},null,()=>phMeasurements[phLabIndex]?.length?null:'Tutki näyte ennen vastaamista.','ph-lab-'+phLabIndex);}
function phResultTable(rows){return rows.length?`<table class="table"><thead><tr><th>Väline</th><th>Havainto</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.text)}</td></tr>`).join('')}</tbody></table>`:'<p>Ei vielä havaintoja.</p>';}
