function renderMetalLaboratory(){view='lab';if(!window.metalInvestigation)window.metalInvestigation={index:0,observed:false};const state=window.metalInvestigation,t=DISPLACEMENTS[state.index],reacts=ChemistryModel.displacement(t.m,t.ion),fields=[selectF('reaction','Havaitaanko syrjäytymisreaktio?',reacts?'kyllä':'ei',['kyllä','ei']),selectF('oxidation','Mikä metalli hapettuu?',reacts?t.m:'ei kumpikaan',[t.m,t.ion,'ei kumpikaan']),selectF('deposit','Mitä metallia pinnalle kertyy?',reacts?t.ion:'ei metallia',[t.m,t.ion,'ei metallia'])];app.innerHTML=pageHead(TITLES[6])+`<div class="task-navigation"><label>Koe <select id="metal-experiment">${DISPLACEMENTS.map((t,i)=>`<option value="${i}" ${i===state.index?'selected':''}>${i+1}. ${METALS[t.m].name} ja ${metalIonWord(t.ion)}</option>`).join('')}</select></label></div><div class="split lab-split"><section class="panel"><h2>${METALS[t.m].name[0].toUpperCase()+METALS[t.m].name.slice(1)} ioniliuoksessa</h2><p>Metalli: ${METALS[t.m].name}. Liuoksen ionit: ${chem(ionFormula(t.ion,METALS[t.ion].q))}.</p><div id="metal-lab-art" class="visual lab-stage">${state.observed?displacementSVG(t,true):paintingStart('displacement-setup','Syrjäytymiskokeen välineet')+'</svg>'}</div><button id="metal-lab-start" class="primary" ${state.observed?'disabled':''}>Lisää metallipala</button><p id="metal-lab-observation" class="log">${state.observed?(reacts?'Pinnalle kertyy metallia.':'Näkyvää syrjäytymisreaktiota ei havaita.'):'Tutki, mitä metallipalan pinnalle tapahtuu.'}</p></section><section class="panel"><h2>Päättele havaintojen perusteella</h2><p>Epäjalompi → jalompi</p><p>Mg, Al, Zn, Fe, Sn, Pb, H, Cu, Ag, Au</p>${formHTML(fields)}</section></div>`;$('#metal-experiment').onchange=e=>{state.index=+e.target.value;state.observed=false;renderMetalLaboratory();};$('#metal-lab-start').onclick=()=>{state.observed=true;$('#metal-lab-art').innerHTML=displacementSVG(t,true);$('#metal-lab-start').disabled=true;$('#metal-lab-observation').textContent=reacts?'Metallin pinnalle muodostuu toista metallia. Lähtömetallia liukenee ioneiksi.':'Näkyvää syrjäytymisreaktiota ei havaita.';};bindForm(fields,reacts?`${METALS[t.m].name[0].toUpperCase()+METALS[t.m].name.slice(1)} hapettuu, ja ${metalIonWord(t.ion)} vastaanottavat elektroneja.`:'Tässä metalliparissa ei havaita syrjäytymistä.',()=>{state.index=(state.index+1)%DISPLACEMENTS.length;state.observed=false;renderMetalLaboratory();},null,()=>state.observed?null:'Lisää metallipala ja tutki havainto.','metal-lab-'+state.index);}
