function neutralTaskPicture(i){if([0,1,2,3,9].includes(i)){const spectators=i===1?[['K',1],['Cl',-1]]:i===2?[['Na',1],['NO3',-1]]:[['Na',1],['Cl',-1]];return neutralModelSVG(spectators);}if(i===10)return neutralModelSVG([['Na',1],['Na',1],['SO4',-2]],2);if(i===11)return neutralModelSVG([['Ca',2],['NO3',-1],['NO3',-1]],2);if(i===7)return svgStart(620,260,'Ammoniumkloridin ionirakenne')+saltSVG({cation:'NH4',anion:'Cl',cq:1,aq:-1},1,1).replace(/^.*?<svg[^>]*>/,'').replace(/<\/svg>$/,'')+'</svg>';if(i===5)return saltSVG(ION_TASKS.find(t=>t.formula==='NaCl'),1,1);if(i===4)return `<table class="table"><thead><tr><th>Emäsliuosta (ml)</th><th>pH</th></tr></thead><tbody>${[[0,2],[10,3],[15,7],[20,12]].map(([v,p])=>`<tr><td>${v}</td><td>${p}</td></tr>`).join('')}</tbody></table>`;return artImage(i===6?'magnesium-oxide':i===8?'carbonate-test':'neutralization');}
renderNeutralTasks=function(){const bank=NEUTRAL_TASKS,i=indices[5]||0,t=bank[i];app.innerHTML=progressHeader(bank,TITLES[4])+`<div class="split training-layout"><section class="panel"><h2>${t.title}</h2><p>${richChemicalText(t.prompt)}</p><div class="visual scientific-model">${neutralTaskPicture(i)}</div></section><section class="panel">${formHTML(t.fields)}</section></div>`;bindForm(t.fields,t.explain,()=>advance(bank,renderNeutralTasks));typesetChemicalText();};
const TITRATION_EQ=[14.7,20.3,25.6];
tit.series={};tit.estimates={};
function saveTitSeries(){tit.series[tit.sample]={volume:tit.volume,records:tit.records.map(r=>({...r}))};}
function setTitSample(i){saveTitSeries();tit.sample=i;const saved=tit.series[i];tit.volume=saved?.volume||0;tit.records=saved?.records.map(r=>({...r}))||[];tit.adding=false;}
function titBracket(records){const sorted=records.slice().sort((a,b)=>a.v-b.v),exact=sorted.find(r=>Math.abs(r.ph-7)<1e-7);if(exact)return {low:exact.v,high:exact.v};const low=sorted.filter(r=>r.ph<7).at(-1),high=sorted.find(r=>r.ph>7);return low&&high?{low:low.v,high:high.v}:null;}
function titDensity(records){const eq=TITRATION_EQ[tit.sample],near=records.slice().sort((a,b)=>a.v-b.v),lo=near.filter(r=>r.v<eq).at(-1),hi=near.find(r=>r.v>eq);return lo&&hi?hi.v-lo.v:Infinity;}
graphSVG=function(unused,maxV,records=[]){const x=v=>58+v/35*485,y=p=>264-p/14*220;let s=svgStart(590,320,'Kirjatut mittauspisteet: emäsliuoksen tilavuus ja pH');for(let p=0;p<=14;p+=2)s+=line(58,y(p),543,y(p),'stroke-opacity=".14"')+txt(43,y(p)+5,p,14,'end');for(let v=0;v<=35;v+=5)s+=line(x(v),44,x(v),264,'stroke-opacity=".1"')+txt(x(v),285,v,14);s+=line(58,264,58,34,'marker-end="url(#arrow)"')+line(58,264,554,264,'marker-end="url(#arrow)"')+txt(18,24,'pH',17)+txt(305,313,'Lisätty emäsliuos (ml)',17);const sorted=records.slice().sort((a,b)=>a.v-b.v);if(sorted.length>1)s+=`<path class="measured-curve" d="${sorted.map((r,i)=>(i?'L':'M')+x(r.v).toFixed(2)+' '+y(r.ph).toFixed(2)).join(' ')}" fill="none" stroke="#172033" stroke-width="2.3"/>`;for(const r of sorted)s+=`<circle class="recorded-point" cx="${x(r.v)}" cy="${y(r.ph)}" r="4" fill="#fff" stroke="#172033" stroke-width="2"/>`;return s+'</svg>';};
renderNeutralization=function(){view='lab';cleanup();cleanup=()=>{};app.innerHTML=pageHead(TITLES[4])+'<div id="neutral-content"></div>';renderTitStage();};
renderTitStage=function(){cleanup();cleanup=()=>{};const eq=TITRATION_EQ[tit.sample],box=$('#neutral-content');if(!box)return;box.innerHTML=`<div class="step">${['Suunnittele','Mittaa','Tulokset','Päätelmät'].map((s,i)=>`<button data-tstage="${i}" class="${tit.stage===i?'active':''}">${s}</button>`).join('')}</div><div id="tit-body"></div>`;box.querySelectorAll('[data-tstage]').forEach(b=>b.onclick=()=>{const stage=+b.dataset.tstage;if(stage>0&&!(done[5]||[]).includes('plan-titration-v3')){const out=$('#feedback');if(out)feedback('Tee tutkimussuunnitelma ennen mittausta.',false);return;}saveTitSeries();tit.stage=stage;renderTitStage();});const body=$('#tit-body');if(tit.stage===0){const fields=[selectF('variable','Mittauksen aikana muutetaan','lisätyn emäsliuoksen tilavuutta',['lisätyn emäsliuoksen tilavuutta','happoliuoksen lämpötilaa','mittarin asteikkoa']),selectF('measure','Mittauksessa seurataan','pH:ta',['pH:ta','hapon massaa','sähkövirtaa']),selectF('fixed','Näytteiden vertailussa pidetään samana','happoliuoksen tilavuus ja emäsliuos',['happoliuoksen tilavuus ja emäsliuos','näytteiden väkevyys ja lisätty emäsmäärä','pH koko tutkimuksen ajan']),selectF('near','Lähellä jyrkkää pH:n muutosta lisätään','0,1 ml kerrallaan',['5 ml kerrallaan','0,1 ml kerrallaan','aina sama suuri annos'])];body.innerHTML=`<div class="split lab-split"><section class="panel"><h2>Kuinka paljon emäsliuosta tarvitaan happoliuoksen neutralointiin?</h2><p>Vertaa suolahappoliuoksia A, B ja C. Jokaisesta otetaan 25 ml:n näyte. Käytössä on sama kaliumhydroksidiliuos ja sama lämpötila.</p>${artImage('titration-setup')}<p>Kirjaa pH ennen ensimmäistä lisäystä. Lisää sitten emäsliuosta ja kirjaa mittaukset. Käytä jyrkän muutoksen lähellä pieniä lisäyksiä.</p></section><section class="panel"><h2>Suunnittele</h2>${formHTML(fields)}</section></div>`;bindForm(fields,'Voit aloittaa näytteiden vertailun.',()=>{tit.stage=1;renderTitStage();},null,null,'plan-titration-v3');}else if(tit.stage===1){body.innerHTML=`<div class="split lab-split"><section class="panel"><div class="compact"><label>Happoliuos <select id="acid-sample">${['A','B','C'].map((s,i)=>`<option value="${i}" ${i===tit.sample?'selected':''}>${s}</option>`).join('')}</select></label><b class="readout" id="tit-volume">${nfi(tit.volume)} <span class="unit">ml emäsliuosta</span></b></div><div id="titration-art" class="visual lab-stage">${titrationSVG(tit.volume,eq)}</div><div class="actions"><button data-add="5">Lisää 5 ml</button><button data-add="1">Lisää 1 ml</button><button data-add="0.1">Lisää 0,1 ml</button><button id="record-ph" class="primary">Kirjaa mittaus</button><button id="reset-tit">Uusi näyte</button></div><p id="tit-message" class="log">Kirjaa alkutilanteen pH.</p></section><section class="panel"><h2>Mittauspisteet</h2><div id="tit-graph" class="visual">${graphSVG(eq,tit.volume,tit.records)}</div><div id="tit-table" class="scroll">${titTable()}</div><p>Suuret lisäykset jättävät jyrkän muutoksen kohdalle pitkiä janoja. Pienet lisäykset näyttävät muutoksen tarkemmin.</p></section></div>`;$('#acid-sample').onchange=e=>{setTitSample(+e.target.value);renderTitStage();};$('#reset-tit').onclick=()=>{tit.volume=0;tit.records=[];saveTitSeries();delete tit.estimates[tit.sample];renderTitStage();};$('#record-ph').onclick=()=>{if(!tit.records.some(r=>Math.abs(r.v-tit.volume)<.001)){tit.records.push({v:tit.volume,ph:ChemistryModel.titrationPH(tit.volume,eq)});saveTitSeries();$('#tit-table').innerHTML=titTable();$('#tit-graph').innerHTML=graphSVG(eq,tit.volume,tit.records);$('#tit-message').textContent='Mittaus kirjattu.';}else $('#tit-message').textContent='Tämä tilavuus on jo kirjattu.';};body.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(tit.adding||tit.volume>=35||!tit.records.some(r=>r.v===0))return;const delta=+b.dataset.add,target=Math.min(35,Math.round((tit.volume+delta)*10)/10),start=tit.volume,wall=performance.now();tit.adding=true;body.querySelectorAll('[data-add],#record-ph,#reset-tit,#acid-sample').forEach(x=>x.disabled=true);const tick=()=>{const f=Math.min(1,(performance.now()-wall)/650);tit.volume=start+(target-start)*f;$('#tit-volume').innerHTML=nfi(tit.volume)+' <span class="unit">ml emäsliuosta</span>';renderPainting($('#titration-art'),titrationSVG(tit.volume,eq,f<1));if(f<1)titTimer=requestAnimationFrame(tick);else{tit.volume=target;tit.adding=false;saveTitSeries();body.querySelectorAll('[data-add],#record-ph,#reset-tit,#acid-sample').forEach(x=>x.disabled=false);body.querySelectorAll('[data-add]').forEach(x=>x.disabled=tit.volume>=35);}};titTimer=requestAnimationFrame(tick);});cleanup=()=>{cancelAnimationFrame(titTimer);tit.adding=false;tit.volume=Math.round(tit.volume*10)/10;saveTitSeries();};}else if(tit.stage===2){saveTitSeries();body.innerHTML=`<div class="split lab-split"><section class="panel"><h2>Näytteen ${'ABC'[tit.sample]} mittaukset</h2><div class="visual">${graphSVG(eq,tit.volume,tit.records)}</div>${titTable()}<button id="export-tit">Lataa mittaukset</button></section><section class="panel"><h2>Vertaa näytteitä</h2><table class="table"><thead><tr><th>Näyte</th><th>Kirjauksia</th><th>Ekvivalenttipiste (ml)</th></tr></thead><tbody>${['A','B','C'].map((s,i)=>`<tr><td>${s}</td><td>${tit.series[i]?.records.length||0}</td><td>${tit.estimates[i]===undefined?'—':nfi(tit.estimates[i])}</td></tr>`).join('')}</tbody></table><p>Arvioi ekvivalenttipiste omista mittauksistasi. Jos kaksi peräkkäistä pH-lukemaa ovat alle ja yli seitsemän, ekvivalenttipiste on niiden välissä.</p><button data-tstage="3" id="interpret-tit">Tee päätelmät →</button></section></div>`;$('#interpret-tit').onclick=()=>{tit.stage=3;renderTitStage();};$('#export-tit').onclick=()=>downloadText('titraus-'+('ABC'[tit.sample])+'.csv','nayte;KOH_ml;pH\n'+tit.records.map(r=>`${'ABC'[tit.sample]};${nfi(r.v)};${nfi(r.ph,2)}`).join('\n'));}else{const bracket=titBracket(tit.records),mid=bracket?(bracket.low+bracket.high)/2:eq,f=F('volume','Arvio neutralointiin tarvittavasta emäsliuoksesta (ml)',mid,'number');f.tolerance=bracket?Math.max(.11,(bracket.high-bracket.low)/2+.01):.11;const fields=[f,selectF('after','Mitä liuoksessa on ylimäärin ekvivalenttipisteen jälkeen?','emästä',['happoa','emästä']),selectF('accuracy','Miten kuvaajan tarkkuutta voi parantaa?','pienentämällä lisäyksiä jyrkän muutoksen lähellä',['pienentämällä lisäyksiä jyrkän muutoksen lähellä','lisäämällä aina suuremman annoksen','kirjaamalla vain loppumittauksen'])];body.innerHTML=`<div class="split lab-split"><section class="panel"><h2>Näytteen ${'ABC'[tit.sample]} päätelmät</h2><div class="visual">${graphSVG(eq,tit.volume,tit.records)}</div>${bracket?`<p>Mittauksesi rajaavat ekvivalenttipisteen välille ${nfi(bracket.low)}–${nfi(bracket.high)} ml.</p>`:'<p>Ekvivalenttipistettä ei voi vielä rajata. Mittaa myös happamalta ja emäksiseltä puolelta.</p>'}<p>${titDensity(tit.records)<=1?'Jyrkän muutoksen lähellä on tiheästi mittauspisteitä.':'Jyrkän muutoksen lähelle tarvitaan lisää mittauspisteitä, jos haluat tarkemman kuvaajan.'}</p></section><section class="panel">${formHTML(fields)}</section></div>`;bindForm(fields,'Arvio perustuu omiin mittaustuloksiisi. Emäksen ylimäärä tekee liuoksesta emäksisen.',()=>{const entered=ChemistryModel.number($('#f-volume').value);tit.estimates[tit.sample]=Number.isFinite(entered)&&$('#f-volume').value.trim()?entered:mid;saveTitSeries();if(Object.keys(tit.estimates).length===3)renderTitComparison();else{setTitSample([0,1,2].find(i=>tit.estimates[i]===undefined));tit.stage=1;renderTitStage();}},null,()=>tit.records.length>=3&&bracket?null:'Kirjaa vähintään kolme mittausta ja mittaa ekvivalenttipisteen molemmilta puolilta.','titration-'+tit.sample);}}
function renderTitComparison(){saveTitSeries();const greatest=Object.entries(tit.estimates).sort((a,b)=>b[1]-a[1])[0][0],fields=[selectF('sample','Mikä näyte tarvitsi eniten emäsliuosta?','ABC'[+greatest],['A','B','C']),selectF('meaning','Mitä tulos osoittaa yhtä suurista suolahapponäytteistä?','tässä näytteessä oli eniten neutraloitavaa happoa',['tässä näytteessä oli eniten neutraloitavaa happoa','kaikissa näytteissä oli yhtä paljon happoa','tässä näytteessä oli aluksi eniten emästä'])];$('#tit-body').innerHTML=`<div class="split"><section class="panel"><h2>Yhteinen päätelmä</h2><table class="table"><thead><tr><th>Näyte</th><th>Oma arvio (ml)</th></tr></thead><tbody>${['A','B','C'].map((s,i)=>`<tr><td>${s}</td><td>${nfi(tit.estimates[i])}</td></tr>`).join('')}</tbody></table></section><section class="panel">${formHTML(fields)}</section></div>`;bindForm(fields,'Sama emäsliuos ja yhtä suuret happoliuoksen näytteet tekevät vertailusta mahdollisen.',()=>{tit.stage=2;renderTitStage();},null,null,'titration-comparison');}
