function specialReactionSVG(i){let s=svgStart(620,355,'Reaktion lähtöaineet ja tuotteet')+txt(145,27,'Lähtöaineet',20)+txt(470,27,'Tuotteet',20)+line(293,164,326,164,'marker-end="url(#arrow)"');if(i===6){s+=`<rect x="48" y="57" width="128" height="67" rx="4" fill="#dce2e9" stroke="#596675"/>`+txt(112,87,'CuO',23)+txt(112,111,'kiinteä',14)+ionNode('H3O',1,75,184)+ionNode('H3O',1,205,184)+ionNode('SO4',-2,140,280);s+=waterParticle(382,76)+waterParticle(486,76)+waterParticle(435,163)+ionNode('Cu',2,386,283)+ionNode('SO4',-2,510,283);}else if(i===8){s+=ionNode('CO3',-2,140,89)+ionNode('H3O',1,73,201)+ionNode('H3O',1,209,201);s+=moleculeToken(442,80,'CO2')+waterParticle(367,173)+waterParticle(477,173)+waterParticle(421,266);s+=txt(144,332,'Karbonaatti ja happo',16)+txt(456,332,'Hiilidioksidia ja vettä',16);}else if(i===12){s+=moleculeToken(141,88,'SO2')+ionNode('Ca',2,139,253)+ionNode('OH',-1,77,174)+ionNode('OH',-1,206,174);s+=ionNode('Ca',2,404,104)+ionNode('SO3',-2,512,104)+waterParticle(458,238)+txt(459,161,'kalsiumsulfiitti',17);}else{s+=moleculeToken(140,88,'CH3COOH')+ionNode('OH',-1,140,219);s+=ionNode('CH3COO',-1,448,89,39)+waterParticle(448,214);s+=txt(144,320,'Etikkahappo ja emäs',16)+txt(455,320,'Asetaatti-ioneja ja vettä',16);}return s+'</svg>';}
