const previousTaskBank=taskBank;taskBank=function(){return page===7?metalTrainingBank():previousTaskBank();};
const previousProgressHeader=progressHeader;
progressHeader=function(bank,title){let html=previousProgressHeader(bank,title);if(page===7){const prefix='metal-v4-'+(metalGroup==='corrosion'?'corrosion':'');const n=(done[7]||[]).filter(k=>metalGroup==='corrosion'?k.startsWith(prefix):k.startsWith('metal-v4-train-')||k.startsWith('metal-v4-metals-')).length;html=html.replace(/Ratkaistu [0-9]+\/[0-9]+/,'Ratkaistu '+n+'/'+bank.length);}else if(page===8){const n=(done[8]||[]).filter(k=>k.startsWith('electro-v4-')).length;html=html.replace(/Ratkaistu [0-9]+\/[0-9]+/,'Ratkaistu '+n+'/'+bank.length);}return html.replace('</select></label>',`</select></label><div class="task-arrows"><button type="button" data-task-step="-1" aria-label="Edellinen tehtävä">← Edellinen</button><button type="button" data-task-step="1" aria-label="Seuraava tehtävä">Seuraava →</button></div>`);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-task-step]');if(!b)return;cleanup();cleanup=()=>{};const bank=taskBank();indices[page]=((indices[page]||0)+Number(b.dataset.taskStep)+bank.length)%bank.length;persist();training();});
function tensionSeries(){return `<aside class="tension-series"><h3>Metallien sähkökemiallinen jännitesarja</h3><div>${['K','Ca','Na','Mg','Al','Zn','Fe','Ni','Sn','Pb','H','Cu','Ag','Pt','Au'].map(s=>`<span class="${s==='H'?'hydrogen':''}">${s}${s==='H'?'<small>vety</small>':''}</span>`).join('')}</div></aside>`;}
function metalBondSVG(){let s=svgStart(580,300,'Metallisidos: positiiviset ionirungot ja yhteiset ulkoelektronit');for(let row=0;row<3;row++)for(let col=0;col<5;col++){const x=95+col*95,y=62+row*82;s+=`<circle cx="${x}" cy="${y}" r="25" fill="#e5e9ee" stroke="#526071" stroke-width="1.5"/>`+txt(x,y+8,'+',27);}for(let row=0;row<3;row++)for(let col=0;col<5;col++){const x=141+col*95,y=91+row*82;s+=`<circle class="electron" cx="${x}" cy="${y}" r="4"><animate attributeName="cx" values="${x-10};${x+10};${x-10}" dur="${2+col*.2}s" repeatCount="indefinite"/></circle>`;}return s+'</svg>';}
function reactionSolution(t){return {Cu:'CuSO4',Ag:'AgNO3',Fe:'FeSO4'}[t.ion];}
function stripShape(s,coat=0,target='Cu') {const copper=s==='Cu',mg=s==='Mg',fill=copper?'url(#reaction-copper)':'url(#reaction-metal)';let out=mg?`<path d="M-13-185Q-27-206-12-218L14-215Q26-201 13-183L17 180Q5 201-15 182Z" fill="${fill}" stroke="#747f88" stroke-width="2"/>`:`<rect x="-33" y="-210" width="66" height="420" rx="5" fill="${fill}" stroke="${copper?'#88513a':'#626b73'}" stroke-width="2"/><path d="M-24-192V183M21-180V194" stroke="${copper?'#e3aa7b':'#c9d0d6'}" stroke-width="2" opacity=".5"/>`;if(coat>0){const c=target==='Cu'?'#a36540':'#aeb6bf';out+=`<g opacity="${coat*.9}">${Array.from({length:43},(_,i)=>`<circle cx="${-20+(i*13)%40}" cy="${-75+(i*31)%260}" r="${3+i%4}" fill="${c}"/>`).join('')}</g>`;}return out;}
function reactionScene(t,insertion=0,reaction=0){const liquid=t.ion==='Cu'?(t.m==='Fe'?mixColor('#4aaba5','#8fbbb1',reaction*.55):mixColor('#4aaba5','#e1e7e5',reaction)):t.ion==='Fe'?mixColor('#b5c9a2','#e1e7e5',reaction):'#d7e1e4';let s=paintingStart('displacement-background','Metallipala pöydällä ja keitinlasi',`<linearGradient id="reaction-metal"><stop stop-color="#6e7882"/><stop offset=".37" stop-color="#ecf0f3"/><stop offset=".67" stop-color="#a9b3bd"/><stop offset="1" stop-color="#697580"/></linearGradient><linearGradient id="reaction-copper"><stop stop-color="#80503a"/><stop offset=".4" stop-color="#d79968"/><stop offset=".65" stop-color="#bd7a4c"/><stop offset="1" stop-color="#804d33"/></linearGradient><clipPath id="reaction-liquid"><path d="M470 425h570v377q0 73-285 73t-285-73Z"/></clipPath>`);s+=`<g clip-path="url(#reaction-liquid)"><rect x="460" y="420" width="590" height="470" fill="${liquid}" opacity=".30"/><ellipse cx="755" cy="428" rx="285" ry="35" fill="${liquid}" opacity=".22"/></g>`;const f=insertion,x=220+(865-220)*f,y=930+(520-930)*f,angle=90-78*f;s+=`<g class="moving-metal" transform="translate(${x} ${y}) rotate(${angle})">${stripShape(t.m,reaction,t.ion)}</g>`+sceneLabel(225,855,t.m+' (s)',160)+sceneLabel(1240,630,unicodeChem(reactionSolution(t))+' (aq)',320);return s+'</svg>';}
function mixColor(a,b,f){return '#'+[1,3,5].map(k=>Math.round(parseInt(a.slice(k,k+2),16)*(1-f)+parseInt(b.slice(k,k+2),16)*f).toString(16).padStart(2,'0')).join('');}
displacementSVG=function(t,observed){return reactionScene(t,observed?1:0,observed&&ChemistryModel.displacement(t.m,t.ion)?1:0);};
const reactionStates={};let reactionTimer=0;
function reactionExercise(t,i,lab=false){const key=(lab?'lab':'train')+'-'+i,state=reactionStates[key]||(reactionStates[key]={observed:false,insertion:0,reaction:0,note:''}),reacts=ChemistryModel.displacement(t.m,t.ion),fields=[selectF('reaction','Havaitaanko kemiallinen reaktio?',reacts?'kyllä':'ei',['kyllä','ei'])];if(reacts){fields.push(i%2?F('particle','Mikä hiukkanen pelkistyy? Anna kemiallinen merkintä.',ionFormula(t.ion,METALS[t.ion].q),'formula'):F('oxidized','Kumpi metalli hapettuu? Anna kemiallinen merkki.',t.m,'formula'));fields.push(F('electron','Kuinka monta elektronia hapettuva atomi luovuttaa?',METALS[t.m].q,'number'));}app.innerHTML=(lab?pageHead(TITLES[6])+`<div class="task-navigation"><label>Koe <select id="metal-experiment">${DISPLACEMENTS.map((a,j)=>`<option value="${j}" ${i===j?'selected':''}>${j+1}. ${METALS[a.m].name} ja ${unicodeChem(reactionSolution(a))}</option>`).join('')}</select></label></div>`:metalHeader())+`<div class="split training-layout"><section class="panel"><h2>Metalli ja suolaliuos</h2><p>Lisää ${METALS[t.m].name}pala liuokseen ja tutki, mitä tapahtuu.</p><p>Metalli: ${chem(t.m)}. Liuos: ${chem(reactionSolution(t))} (aq).</p><div id="metal-art" class="visual lab-stage">${reactionScene(t,state.insertion,state.reaction)}</div><button id="add-metal" class="primary" ${state.observed?'disabled':''}>Lisää ${t.m==='Mg'?'magnesiumnauha':'metallipala'}</button><label class="observation-field">Kirjaa havaintosi.<textarea id="reaction-notes" rows="2">${esc(state.note)}</textarea></label></section><section class="panel">${tensionSeries()}${formHTML(fields)}</section></div>`;if(lab)$('#metal-experiment').onchange=e=>{window.metalInvestigation.index=+e.target.value;renderMetalLaboratory();};$('#reaction-notes').oninput=e=>state.note=e.target.value;bindForm(fields,'',()=>lab?(window.metalInvestigation.index=(i+1)%DISPLACEMENTS.length,renderMetalLaboratory()):advance(METAL_MAIN,renderMetals),null,()=>!state.observed?'Lisää metallipala ja seuraa koetta.':!state.note.trim()?'Kirjaa havaintosi ennen päätelmää.':null,'metal-v4-'+key);$('#add-metal').onclick=()=>{const start=performance.now();$('#add-metal').disabled=true;const tick=()=>{const elapsed=performance.now()-start;state.insertion=Math.min(1,elapsed/1200);state.reaction=reacts?Math.min(1,Math.max(0,elapsed-1200)/5000):0;renderPainting($('#metal-art'),reactionScene(t,state.insertion,state.reaction));if(elapsed<6500)reactionTimer=requestAnimationFrame(tick);else state.observed=true;};reactionTimer=requestAnimationFrame(tick);};cleanup=()=>{cancelAnimationFrame(reactionTimer);if(!state.observed){state.insertion=0;state.reaction=0;}};if(!lab)$('#next-task').hidden=true;typesetChemicalText();}
function metalHeader(){return progressHeader(metalTrainingBank(),TITLES[6])+`<nav class="tabs sub-tabs"><button data-metal-group="metals" class="${metalGroup==='metals'?'active':''}">Metallit</button><button data-metal-group="corrosion" class="${metalGroup==='corrosion'?'active':''}">Korroosio</button></nav>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-metal-group]');if(!b)return;cleanup();cleanup=()=>{};metalGroupIndices[metalGroup]=indices[7]||0;metalGroup=b.dataset.metalGroup;indices[7]=metalGroupIndices[metalGroup]||0;renderMetals();});
renderMetals=function(){view='train';cleanup();cleanup=()=>{};const bank=metalTrainingBank();if((indices[7]||0)>=bank.length)indices[7]=0;const i=indices[7]||0,t=bank[i];if(t.kind==='displace'){reactionExercise(t,i);return;}const picture=t.kind==='bond'?`<div class="visual scientific-model">${metalBondSVG()}</div><p class="model-key">Ympyrät: positiiviset ionirungot. Pisteet: yhteiset ulkoelektronit.</p>`:artImage(t.art);app.innerHTML=metalHeader()+`<div class="split training-layout"><section class="panel"><h2>${t.title}</h2><p>${t.prompt}</p>${picture}</section><section class="panel">${formHTML(t.fields)}</section></div>`;bindForm(t.fields,t.explain,()=>advance(bank,renderMetals),null,null,'metal-v4-'+metalGroup+'-'+i);$('#next-task').hidden=true;typesetChemicalText();};
