const mysteryRemember={};
renderMystery=function(newSet=false){view='lab';originalMystery(newSet);const count=app.querySelector('.counter');count.className='task-navigation';count.innerHTML=`<label>Tutkimus <select id="mystery-selector">${UNKNOWN_SETS.map((s,i)=>`<option value="${i}" ${i===myst.index?'selected':''}>${i+1}. ${s.title}</option>`).join('')}</select></label><div class="task-arrows"><button id="mystery-prev">← Edellinen</button><button id="mystery-next">Seuraava →</button></div>`;const go=i=>{mysteryRemember[myst.index]={samples:myst.samples,observations:myst.observations,selected:myst.selected,test:myst.test};myst.index=(i+UNKNOWN_SETS.length)%UNKNOWN_SETS.length;Object.assign(myst,mysteryRemember[myst.index]||{samples:[],observations:[],selected:0,test:''});renderMystery();};$('#mystery-selector').onchange=e=>go(+e.target.value);$('#mystery-prev').onclick=()=>go(myst.index-1);$('#mystery-next').onclick=()=>go(myst.index+1);app.querySelector('.warning').textContent='Tuntemattomia aineita ei maisteta. Oikeat kokeet tehdään opettajan ohjauksessa.';$('#next-task').onclick=()=>go(myst.index+1);};

let phLaboratoryKind='samples',neutralLaboratoryKind='titration';
const sampleLaboratory=renderPHLaboratory,titrationLaboratory=renderNeutralization;
