document.addEventListener('click',e=>{const ph=e.target.closest('[data-phkind]'),n=e.target.closest('[data-nkind]');if(!ph&&!n)return;cleanup();cleanup=()=>{};if(ph){phLaboratoryKind=ph.dataset.phkind;renderPHLaboratory();}else{neutralLaboratoryKind=n.dataset.nkind;renderNeutralization();}});
const oxideStudy={mgo:0,so2:0,complete:{mgo:false,so2:false},running:null};let oxideTimer=0;
function btsFluid(ph){return ph<=7?mixColor('#eed065','#8eb68d',Math.max(0,Math.min(1,ph-6))):mixColor('#8eb68d','#82a4ca',Math.max(0,Math.min(1,(ph-7)/.6)));}
function oxideScene(){const left=7+3.3*(1-Math.exp(-4*oxideStudy.mgo))/(1-Math.exp(-4)),right=7-3.2*(1-Math.exp(-4*oxideStudy.so2))/(1-Math.exp(-4));let s=paintingStart('oxide-study','Magnesiumoksidia ja rikkidioksidia lisätään eri vesiastioihin',`<clipPath id="oxide-left"><path d="M367 505H661V709Q661 754 514 754Q367 754 367 709Z"/></clipPath><clipPath id="oxide-right"><path d="M1180 505H1477V710Q1477 754 1328 754Q1180 754 1180 710Z"/></clipPath>`);for(const [id,x,w,p] of [['left',367,294,left],['right',1180,297,right]])s+=`<g clip-path="url(#oxide-${id})"><rect x="${x}" y="498" width="${w}" height="262" fill="${btsFluid(p)}" opacity=".37"/></g>`;if(oxideStudy.mgo>0){s+=Array.from({length:24},(_,i)=>`<circle cx="${415+(i*31)%195}" cy="${oxideStudy.running==='mgo'?445+((performance.now()*.10+i*33)%269):714+(i%3)*5}" r="${3+i%4}" fill="#fff" stroke="#d7d9dc" stroke-width="1"/>`).join('');}if(oxideStudy.running==='so2'){s+=`<path d="M920 640Q900 620 921 589Q925 610 936 617Q948 631 934 643Z" fill="#5286bf" opacity=".8"/>`+Array.from({length:9},(_,i)=>`<circle cx="${1370+(i%3-1)*9}" cy="${622-((performance.now()*.08+i*17)%124)}" r="${4+i%3}" fill="url(#gas-bubble)"/>`).join('');}return s+sceneLabel(510,895,'MgO (s)',210)+sceneLabel(1330,895,'SO₂ (g)',210)+'</svg>';}
function renderOxides(){view='lab';cleanup();cleanup=()=>{};const fields=[selectF('start','BTS:n väri puhtaassa vedessä','vihreä',['keltainen','vihreä','sininen']),selectF('mgoColor','BTS:n väri MgO:n lisäämisen jälkeen','sininen',['keltainen','vihreä','sininen']),selectF('mgoPH','Liuos MgO:n lisäämisen jälkeen on','emäksinen',['hapan','neutraali','emäksinen']),selectF('soColor','BTS:n väri SO2:n lisäämisen jälkeen','keltainen',['keltainen','vihreä','sininen']),selectF('soPH','Liuos SO2:n lisäämisen jälkeen on','hapan',['hapan','neutraali','emäksinen']),selectF('mgType','Magnesium on','metalli',['metalli','epämetalli']),selectF('sType','Rikki on','epämetalli',['metalli','epämetalli']),selectF('metalOxide','Tutkitun metallioksidin lisäys tekee liuoksesta','emäksisen',['happaman','neutraalin','emäksisen']),selectF('nonmetalOxide','Tutkitun epämetallioksidin lisäys tekee liuoksesta','happaman',['happaman','neutraalin','emäksisen'])];app.innerHTML=pageHead(TITLES[3])+laboratoryMenu('ph')+`<div class="split lab-split"><section class="panel"><h2>Miten oksidi vaikuttaa veden happamuuteen?</h2><p>Molemmissa astioissa on sama määrä puhdasta vettä ja BTS-indikaattoria. Lisää toiseen magnesiumoksidijauhetta. Polta sitten rikkiä ja johda syntyvä kaasu toiseen astiaan.</p><div id="oxide-art" class="visual lab-stage">${oxideScene()}</div><div class="actions"><button id="oxide-mgo" ${oxideStudy.complete.mgo?'disabled':''}>Lisää MgO-jauhetta</button><button id="oxide-so2" ${oxideStudy.complete.so2?'disabled':''}>Polta rikkiä ja johda kaasu veteen</button><button id="oxide-reset">Aloita uudelleen</button></div><p class="tiny">Rikin polttokoe on opettajan demonstraatio.</p></section><section class="panel"><h2>Tulkitse värinmuutokset</h2>${formHTML(fields)}</section></div>`;bindForm(fields,'Magnesiumoksidi tekee liuoksesta emäksisen. Osa jauheesta jää kiinteäksi. Rikkidioksidi tekee liuoksesta happaman.',()=>{phLaboratoryKind='samples';renderPHLaboratory();},null,()=>oxideStudy.complete.mgo&&oxideStudy.complete.so2?null:'Tutki molemmat oksidit ennen vastaamista.','oxides-v4');for(const k of ['mgo','so2'])$('#oxide-'+k).onclick=()=>{oxideStudy.running=k;const start=performance.now();app.querySelectorAll('#oxide-mgo,#oxide-so2,#oxide-reset').forEach(b=>b.disabled=true);const tick=()=>{oxideStudy[k]=Math.min(1,(performance.now()-start)/5000);renderPainting($('#oxide-art'),oxideScene());if(oxideStudy[k]<1)oxideTimer=requestAnimationFrame(tick);else{oxideStudy.complete[k]=true;oxideStudy.running=null;renderPainting($('#oxide-art'),oxideScene());$('#oxide-mgo').disabled=oxideStudy.complete.mgo;$('#oxide-so2').disabled=oxideStudy.complete.so2;$('#oxide-reset').disabled=false;}};oxideTimer=requestAnimationFrame(tick);};$('#oxide-reset').onclick=()=>{Object.assign(oxideStudy,{mgo:0,so2:0,complete:{mgo:false,so2:false},running:null});renderOxides();};cleanup=()=>{cancelAnimationFrame(oxideTimer);if(oxideStudy.running){oxideStudy[oxideStudy.running]=0;oxideStudy.running=null;}};typesetChemicalText();}

const bufferStudy={stage:1,volume:0,records:[],measured:false,adding:false};let bufferTimer=0;
function bufferPH(kind,v){const V=(50+v)/1000,cl=.1*v/1000/V;if(kind==='water')return -Math.log10((cl+Math.sqrt(cl*cl+4e-14))/2);const ka=Math.pow(10,-4.76),total=.0005/V,na=.00025/V;let lo=0,hi=14;for(let i=0;i<80;i++){const p=(lo+hi)/2,h=Math.pow(10,-p),balance=h+na-cl-total*ka/(ka+h)-1e-14/h;if(balance>0)lo=p;else hi=p;}return (lo+hi)/2;}
function bufferScene(kind,adding=false){const ph=bufferPH(kind,bufferStudy.volume);let s=phLabSVG({ph},'meter',bufferStudy.measured).replace('>'+nfi(ph)+'</text>','>'+nfi(ph,2)+'</text>').replace('</svg>','');if(false)s+=`<g clip-path="url(#ph-liquid)"><rect x="306" y="438" width="502" height="400" fill="#fffdf8" opacity=".70"/><ellipse cx="557" cy="438" rx="250" ry="38" fill="#fffdf8" opacity=".75"/></g>`;if(adding)s+=`<path d="M545 235h25v117h-25Z" fill="#bfc5cb" stroke="#646d77"/><path d="M553 352v30" stroke="#666" stroke-width="4"/>`+Array.from({length:3},(_,i)=>`<path d="M553 0q-8 15 0 21q8-6 0-21" transform="translate(0 ${390+((performance.now()*.11+i*19)%115)})" fill="#c1cbd0"/>`).join('');return s+'</svg>';}
function bufferTable(){return `<table class="table"><thead><tr><th>HCl (ml)</th><th>Puskuriliuoksen pH</th><th>Veden pH</th></tr></thead><tbody>${bufferStudy.records.map(r=>`<tr><td>${nfi(r.v)}</td><td>${nfi(r.milk,2)}</td><td>${nfi(r.water,2)}</td></tr>`).join('')||'<tr><td colspan="3">Ei kirjattuja mittauksia.</td></tr>'}</tbody></table>`;}
function bufferGraph(){const records=bufferStudy.records.slice().sort((a,b)=>a.v-b.v),x=v=>55+v/5*470,y=p=>278-p/7*220;let s=svgStart(570,335,'Puskuriliuoksen ja veden mitatut pH-arvot');for(let p=0;p<=7;p++)s+=line(55,y(p),525,y(p),'stroke-opacity=".12"')+txt(40,y(p)+5,p,14);for(let v=0;v<=5;v+=1)s+=txt(x(v),300,v,14);s+=line(55,58,55,278)+line(55,278,525,278)+txt(20,26,'pH',17)+txt(290,326,'Lisätty HCl (ml)',17);for(const kind of ['milk','water']){if(records.length>1)s+=`<path d="${records.map((r,i)=>(i?'L':'M')+x(r.v)+' '+y(r[kind])).join(' ')}" stroke="${kind==='milk'?'#172033':'#738397'}" stroke-width="2.5" ${kind==='water'?'stroke-dasharray="6 5"':''} fill="none"/>`;for(const r of records)s+=`<circle cx="${x(r.v)}" cy="${y(r[kind])}" r="4" fill="#fff" stroke="${kind==='milk'?'#172033':'#738397'}"/>`;}return s+'</svg>';}
function renderBuffer(){view='lab';cleanup();cleanup=()=>{};app.innerHTML=pageHead(TITLES[4])+laboratoryMenu('neutral')+`<section class="panel buffer-info"><p><b>Puskuriliuos</b> vastustaa pH:n muutoksia, kun siihen lisätään pieni määrä happoa tai emästä. Puskurikyky on rajallinen. Esimerkiksi veren ja syljen puskurit auttavat pitämään pH:n sopivalla alueella.</p><p>Tässä tutkitaan laimeaa asetaattipuskuria, joka sisältää etikkahappoa ja natriumasetaattia. Näytteissä on aluksi 50 ml puskuriliuosta tai puhdasta vettä. Lisää molempiin yhtä paljon samaa suolahappoliuosta ja vertaa pH:n muutoksia. Kirjaa lähtötilanne ja useita happolisäyksiä.</p></section><div class="step">${['Tutkimus ja havainnot','Päätelmät'].map((x,j)=>{const i=j+1;return `<button data-bufferstage="${i}" class="${bufferStudy.stage===i?'active':''}">${x}</button>`;}).join('')}</div><div id="buffer-content"></div>`;app.querySelectorAll('[data-bufferstage]').forEach(b=>b.onclick=()=>{bufferStudy.stage=+b.dataset.bufferstage;renderBuffer();});const box=$('#buffer-content');if(bufferStudy.stage===1){box.innerHTML=`<div class="buffer-stages"><section class="panel"><h2>Asetaattipuskuri</h2><div id="buffer-milk" class="visual lab-stage">${bufferScene('milk')}</div></section><section class="panel"><h2>Vesi</h2><div id="buffer-water" class="visual lab-stage">${bufferScene('water')}</div></section></div><section class="panel"><div class="compact"><b id="buffer-volume">Happoliuosta kummassakin näytteessä: ${nfi(bufferStudy.volume)} ml</b><div class="actions"><button data-bufferadd="0.2">Lisää 0,2 ml</button><button data-bufferadd="1">Lisää 1 ml</button><button data-bufferadd="0.5">Lisää 0,5 ml</button><button id="buffer-measure" class="primary">Mittaa ja kirjaa pH-arvot</button><button id="buffer-reset">Uudet näytteet</button></div></div><div id="buffer-records">${bufferTable()}</div></section>`;const redraw=()=>{renderPainting($('#buffer-milk'),bufferScene('milk',bufferStudy.adding));renderPainting($('#buffer-water'),bufferScene('water',bufferStudy.adding));$('#buffer-volume').textContent='Happoliuosta kummassakin näytteessä: '+nfi(bufferStudy.volume)+' ml';};$('#buffer-measure').onclick=()=>{bufferStudy.measured=true;if(!bufferStudy.records.some(r=>Math.abs(r.v-bufferStudy.volume)<.001))bufferStudy.records.push({v:bufferStudy.volume,milk:bufferPH('milk',bufferStudy.volume),water:bufferPH('water',bufferStudy.volume)});$('#buffer-records').innerHTML=bufferTable();redraw();};app.querySelectorAll('[data-bufferadd]').forEach(b=>b.onclick=()=>{if(bufferStudy.adding||bufferStudy.volume>=5)return;const start=bufferStudy.volume,target=Math.min(5,Math.round((start+Number(b.dataset.bufferadd))*10)/10),wall=performance.now();bufferStudy.adding=true;bufferStudy.measured=false;app.querySelectorAll('[data-bufferadd],#buffer-measure,#buffer-reset,[data-bufferstage]').forEach(x=>x.disabled=true);const tick=()=>{const f=Math.min(1,(performance.now()-wall)/800);bufferStudy.volume=start+(target-start)*f;redraw();if(f<1)bufferTimer=requestAnimationFrame(tick);else{bufferStudy.volume=target;bufferStudy.adding=false;redraw();app.querySelectorAll('[data-bufferadd],#buffer-measure,#buffer-reset,[data-bufferstage]').forEach(x=>x.disabled=false);app.querySelectorAll('[data-bufferadd]').forEach(x=>x.disabled=bufferStudy.volume>=5);}};bufferTimer=requestAnimationFrame(tick);});$('#buffer-reset').onclick=()=>{bufferStudy.volume=0;bufferStudy.records=[];bufferStudy.measured=false;renderBuffer();};cleanup=()=>{cancelAnimationFrame(bufferTimer);bufferStudy.adding=false;bufferStudy.volume=Math.round(bufferStudy.volume*10)/10;};}else{const first=bufferStudy.records.filter(r=>r.v>0).sort((a,b)=>a.v-b.v)[0],fields=[F('milk','Puskuriliuoksen pH:n lasku ensimmäisessä kirjatussa happolisäyksessä',first?bufferPH('milk',0)-first.milk:0,'number'),F('water','Veden pH:n lasku samassa happolisäyksessä',first?7-first.water:0,'number'),selectF('buffer','Mikä havainto osoittaa puskuriliuoksen puskurivaikutuksen?','puskuriliuoksen pH muuttuu pienessä happolisäyksessä vähemmän',['puskuriliuoksen pH muuttuu pienessä happolisäyksessä vähemmän','puskuriliuos ja vesi muuttuvat aina yhtä happamiksi','puskuriliuoksen pH pysyy kaikilla happomäärillä samana','veden pH muuttuu happolisäyksessä emäksiseksi'])];fields[0].tolerance=fields[1].tolerance=.06;box.innerHTML=`<div class="split training-layout"><section class="panel"><h2>Vertaa omia mittauksiasi</h2><div class="visual">${bufferGraph()}</div><p>Yhtenäinen viiva: puskuriliuos. Katkoviiva: vesi.</p>${bufferTable()}</section><section class="panel">${formHTML(fields)}</section></div>`;bindForm(fields,'Puskuriliuos vastustaa pH:n muutosta. Sen puskurivaikutus on rajallinen: riittävän suuri happolisäys laskee myös puskuriliuoksen pH:ta.',()=>{bufferStudy.stage=1;renderBuffer();},null,()=>bufferStudy.records.some(r=>r.v===0)&&bufferStudy.records.length>=3&&first?.v<=1?null:'Kirjaa lähtötilanne ja vähintään kaksi happolisäystä. Tee ensimmäinen kirjattava lisäys enintään 1 ml:n annoksena.','buffer-v4');}typesetChemicalText();}

