renderElectroTasks=function(){view='train';cleanup();cleanup=()=>{};if((indices[8]||0)>=ELECTRO_TASKS.length)indices[8]=0;const i=indices[8]||0,t=ELECTRO_TASKS[i];app.innerHTML=progressHeader(ELECTRO_TASKS,TITLES[7])+`<div class="split training-layout"><section class="panel"><h2>${t.title}</h2><p>${t.prompt}</p>${artImage(t.art)}</section><section class="panel">${formHTML(t.fields)}</section></div>`;bindForm(t.fields,t.explain,()=>advance(ELECTRO_TASKS,renderElectroTasks),null,null,'electro-v4-'+i);$('#next-task').hidden=true;typesetChemicalText();};
function signedCellVoltage(a,b,reversed=false){const m=ChemistryModel.cell(a,b);return m.voltage*(m.anode===a?1:-1)*(reversed?-1:1);}
cellSVG=function(a,b,unused,on){const u=signedCellVoltage(a,b,!!electro.reversed);return paintingStart('cell-background','Kaksi metallilevyä samassa elektrolyyttiliuoksessa')+`<text x="770" y="105" text-anchor="middle" font-family="monospace" font-size="51" fill="#252525">${on?nfi(u,2)+' V':'—'}</text>`+sceneLabel(635,345,a,170)+sceneLabel(905,345,b,170)+'</svg>';};
const baseElectroStage=renderElectroStage;
renderElectroStage=function(){baseElectroStage();if(electro.kind==='cell'&&electro.stage===1){const connect=$('#connect-cell'),old=connect.onclick;connect.onclick=()=>{old();$('#cell-message').textContent=electro.on?'Mittari on kytketty.':'Mittari on irrotettu.';};connect.insertAdjacentHTML('afterend','<button id="reverse-cell">Vaihda mittarin johtimet keskenään</button>');$('#reverse-cell').onclick=()=>{electro.reversed=!electro.reversed;$('#cell-art').innerHTML=cellSVG(electro.a,electro.b,false,electro.on);};$('#record-cell').onclick=()=>{if(!electro.on)return;const u=signedCellVoltage(electro.a,electro.b,!!electro.reversed);if(!electro.records.some(r=>r.a===electro.a&&r.b===electro.b&&Math.abs(r.u-u)<.001))electro.records.push({a:electro.a,b:electro.b,u});$('#cell-table').innerHTML=cellTable();};}if(electro.kind==='cell'&&electro.stage===3){const fields=[F('metal','Kumpi metalli hapettuu Zn–Cu-parissa? Anna kemiallinen merkki.','Zn','formula'),F('ion','Muodostuvan ionin kemiallinen merkintä','Zn^2+','formula'),F('e','Kuinka monta elektronia hapettuva atomi luovuttaa?',2,'number')];const body=$('#electro-body');body.innerHTML=`<div class="split training-layout"><section class="panel"><h2>Omat mittaukset</h2>${cellTable()}</section><section class="panel">${formHTML(fields)}</section></div>`;bindForm(fields,'',()=>{electro.kind='plating';electro.stage=0;renderElectrochem();},null,()=>new Set(electro.records.map(r=>[r.a,r.b].sort().join('-'))).size>=3?null:'Tutki vähintään kolme eri metalliparia.','cell-v4');}}
const baseElectroLaboratory=renderElectrochem;
renderElectrochem=function(){if(electro.kind==='mystery')renderMetalMystery();else {baseElectroLaboratory();app.querySelector('.sub-tabs').insertAdjacentHTML('beforeend','<button data-ekind="mystery">Tunnista metallilevyt</button>');app.querySelector('[data-ekind="mystery"]').onclick=()=>{electro.kind='mystery';renderElectrochem();};}};
const metalMystery={metals:ChemistryModel.shuffle(['Zn','Fe','Ag'],92731),a:0,b:1,acid:0,acidTested:[],acidNotes:{},records:[],reversed:false,on:false,gas:false};
function mysteryCellScene(){const u=signedCellVoltage(metalMystery.metals[metalMystery.a],metalMystery.metals[metalMystery.b],metalMystery.reversed),left=String.fromCharCode(65+metalMystery.a),right=String.fromCharCode(65+metalMystery.b);return paintingStart('cell-background','Tuntemattomat metallilevyt ja jännitemittari')+`<text x="770" y="105" text-anchor="middle" font-family="monospace" font-size="51" fill="#252525">${metalMystery.on?nfi(u,2)+' V':'—'}</text>`+sceneLabel(635,345,left,95)+sceneLabel(905,345,right,95)+sceneLabel(635,265,metalMystery.reversed?'Punainen':'Musta',195)+sceneLabel(905,265,metalMystery.reversed?'Musta':'Punainen',195)+'</svg>';}
function mysteryAcidScene(){const t={m:metalMystery.metals[metalMystery.acid],ion:'Ag'},gas=metalMystery.gas&&t.m!=='Ag';let s=paintingStart('displacement-background','Erillinen metallinäyte suolahappoliuoksessa',`<linearGradient id="reaction-metal"><stop stop-color="#6e7882"/><stop offset=".4" stop-color="#ecf0f3"/><stop offset="1" stop-color="#697580"/></linearGradient><linearGradient id="reaction-copper"><stop stop-color="#80503a"/><stop offset=".4" stop-color="#d79968"/><stop offset="1" stop-color="#804d33"/></linearGradient>`);s+=`<g transform="translate(820 ${metalMystery.gas?615:940}) rotate(${metalMystery.gas?9:90})">${stripShape(t.m)}</g>`;if(gas)s+=Array.from({length:14},(_,i)=>`<circle cx="${775+(i*19)%98}" cy="${820-((performance.now()*.08+i*29)%370)}" r="${4+i%4}" fill="url(#gas-bubble)" class="mystery-bubble"/>`).join('');return s+sceneLabel(1230,630,'HCl (aq)',240)+sceneLabel(235,875,String.fromCharCode(65+metalMystery.acid),90)+'</svg>';}
function metalMysteryTable(){return `<table class="table"><thead><tr><th>Musta johdin</th><th>Punainen johdin</th><th>Jännite (V)</th></tr></thead><tbody>${metalMystery.records.map(r=>`<tr><td>${'ABCD'[r.black]}</td><td>${'ABCD'[r.red]}</td><td>${nfi(r.u,2)}</td></tr>`).join('')||'<tr><td colspan="3">Ei kirjattuja mittauksia.</td></tr>'}</tbody></table>`;}
function mysteryPairsConnected(){const seen=new Set([0]);let old=0;while(seen.size!==old){old=seen.size;for(const r of metalMystery.records)if(seen.has(r.black)||seen.has(r.red)){seen.add(r.black);seen.add(r.red);}}return seen.size===3&&new Set(metalMystery.records.map(r=>[r.black,r.red].sort().join('-'))).size>=2;}
let metalMysteryTimer=0;
function renderMetalMystery(){view='lab';cleanup();cleanup=()=>{};const options=i=>['A','B','C'].map((x,j)=>`<option value="${j}" ${i===j?'selected':''}>${x}</option>`).join(''),fields=metalMystery.metals.map((s,i)=>F('metal'+i,'Levyn '+String.fromCharCode(65+i)+' kemiallinen merkki',s,'formula'));fields.push(F('gas','Suolahappokokeessa syntyvän kaasun kaava','H2','formula'));app.innerHTML=pageHead(TITLES[7])+`<nav class="tabs sub-tabs"><button data-return-cell>Sähkökemiallinen pari</button><button data-return-plating>Veden elektrolyysi</button><button class="active">Tunnista metallilevyt</button></nav><section class="panel mystery-intro"><h2>Tunnista kolme metallilevyä</h2><p>Metallilevyjen A–C tunnistuslaput ovat kadonneet. Levyt ovat sinkkiä, rautaa ja hopeaa, mutta et tiedä, mikä levy on mitäkin metallia. Tunnista levyt kokeiden avulla. Tutki jokaisesta levystä erillinen näyte suolahapolla ja vertaa levyparien jännitteitä samassa laimeassa happoliuoksessa. Käytä apuna jännitesarjaa.</p>${tensionSeries()}</section><div class="split lab-split"><section class="panel"><h2>Suolahappokoe</h2><label>Levyn näyte <select id="acid-unknown">${options(metalMystery.acid)}</select></label><div id="unknown-acid-art" class="visual lab-stage">${mysteryAcidScene()}</div><button id="unknown-acid-test">Lisää näyte suolahappoon</button><label class="observation-field">Kirjaa havaintosi.<input id="unknown-acid-note" value="${esc(metalMystery.acidNotes[metalMystery.acid]||'')}" autocomplete="off"></label><button id="unknown-acid-record">Kirjaa havainto</button><div id="unknown-acid-notes">${Object.entries(metalMystery.acidNotes).map(([i,n])=>`<p><b>${'ABCD'[+i]}</b>: ${esc(n)}</p>`).join('')}</div></section><section class="panel"><h2>Jännitemittaus</h2><div class="compact"><label>Vasen levy<select id="unknown-a">${options(metalMystery.a)}</select></label><label>Oikea levy<select id="unknown-b">${options(metalMystery.b)}</select></label></div><div id="unknown-cell-art" class="visual lab-stage">${mysteryCellScene()}</div><div class="actions"><button id="unknown-connect">Mittaa jännite</button><button id="unknown-record">Kirjaa jännite</button></div><div id="unknown-meter-log">${metalMysteryTable()}</div></section></div><section class="panel"><h2>Mitä metallia kukin levy on?</h2>${formHTML(fields)}</section>`;app.querySelector('[data-return-cell]').onclick=()=>{electro.kind='cell';renderElectrochem();};app.querySelector('[data-return-plating]').onclick=()=>{electro.kind='water';renderElectrochem();};$('#acid-unknown').onchange=e=>{metalMystery.acid=+e.target.value;metalMystery.gas=false;renderMetalMystery();};$('#unknown-acid-test').onclick=()=>{cancelAnimationFrame(metalMysteryTimer);metalMystery.gas=true;if(!metalMystery.acidTested.includes(metalMystery.acid))metalMystery.acidTested.push(metalMystery.acid);const start=performance.now();const tick=()=>{renderPainting($('#unknown-acid-art'),mysteryAcidScene());if(performance.now()-start<7000)metalMysteryTimer=requestAnimationFrame(tick);};metalMysteryTimer=requestAnimationFrame(tick);};$('#unknown-acid-record').onclick=()=>{const note=$('#unknown-acid-note').value.trim();if(!metalMystery.acidTested.includes(metalMystery.acid)||!note){feedback('Tutki näyte ja kirjoita havainto ennen kirjaamista.',false);return;}metalMystery.acidNotes[metalMystery.acid]=note;$('#unknown-acid-notes').innerHTML=Object.entries(metalMystery.acidNotes).map(([i,n])=>`<p><b>${'ABCD'[+i]}</b>: ${esc(n)}</p>`).join('');};const redraw=()=>{renderPainting($('#unknown-cell-art'),mysteryCellScene());};for(const k of ['a','b'])$('#unknown-'+k).onchange=e=>{metalMystery[k]=+e.target.value;metalMystery.on=false;redraw();};$('#unknown-connect').onclick=()=>{metalMystery.reversed=false;metalMystery.on=true;redraw();};$('#unknown-record').onclick=()=>{if(!metalMystery.on){feedback('Mittaa jännite ennen kirjaamista.',false);return;}const black=metalMystery.reversed?metalMystery.b:metalMystery.a,red=metalMystery.reversed?metalMystery.a:metalMystery.b,u=signedCellVoltage(metalMystery.metals[metalMystery.a],metalMystery.metals[metalMystery.b],metalMystery.reversed);if(!metalMystery.records.some(r=>r.black===black&&r.red===red))metalMystery.records.push({black,red,u});$('#unknown-meter-log').innerHTML=metalMysteryTable();};bindForm(fields,'',()=>{electro.kind='cell';electro.stage=0;renderElectrochem();},null,()=>Object.keys(metalMystery.acidNotes).length<3?'Tutki kaikki kolme levynäytettä suolahapolla ja kirjaa havainnot.':!mysteryPairsConnected()?'Vertaa vähintään kahta eri levyparia niin, että kaikki levyt liittyvät samaan mittausketjuun.':null,'metal-mystery-v4');cleanup=()=>cancelAnimationFrame(metalMysteryTimer);typesetChemicalText();}

loadStore=function(){let data={};try{const current=localStorage.getItem('mafyke-kemia8-v4');if(current)data=JSON.parse(current);else{data=JSON.parse(localStorage.getItem('mafyke-kemia8-v3')||localStorage.getItem('mafyke-kemia8-v2')||'{}');for(const p of [7,8]){if(data.done?.[p])data.done[p]=data.done[p].filter(k=>!String(k).startsWith('task-')&&!String(k).startsWith('quiz'));if(data.indices)data.indices[p]=0;}}}catch(e){}indices=data.indices||{};done=data.done||{};};
persist=function(){try{localStorage.setItem('mafyke-kemia8-v4',JSON.stringify({indices,done}));}catch(e){}};

const observationElectroStage=renderElectroStage;
renderElectroStage=function(){observationElectroStage();if(electro.kind!=='plating')return;if(electro.stage===1){const panels=$('#electro-body').querySelectorAll('.panel');panels[1].innerHTML='<h3>Kirjaa havaintosi.</h3><label class="observation-field">Mitä havaitset esineen ja kuparilevyn pinnoilla?<textarea id="plating-notes" rows="5">'+esc(electro.plateNotes||'')+'</textarea></label>';$('#plating-notes').oninput=e=>electro.plateNotes=e.target.value;}else if(electro.stage===2){$('#electro-body').innerHTML='<div class="split training-layout"><section class="panel"><div class="visual lab-stage">'+platingSVG(false,electro.progress,true)+'</div></section><section class="panel"><h2>Omat havainnot</h2><p>'+esc(electro.plateNotes||'Et ole vielä kirjannut havaintoja.')+'</p></section></div>';}else if(electro.stage===3){const fields=[F('pole','Mihin napaan esine oli kytketty?',['miinusnapaan','miinusnapa','-']),F('ion','Mikä hiukkanen pelkistyi? Anna kemiallinen merkintä.','Cu^2+','formula'),F('e','Kuinka monta elektronia yksi kupari-ioni vastaanotti?',2,'number'),selectF('mass','Kuparilevyn massa','pieneni',['pieneni','kasvoi','säilyi samana'])];$('#electro-body').innerHTML='<div class="split training-layout"><section class="panel"><h2>Omat havainnot</h2><p>'+esc(electro.plateNotes||'')+'</p>'+artImage('plating-setup')+'</section><section class="panel">'+formHTML(fields)+'</section></div>';bindForm(fields,'',()=>{electro.kind='cell';electro.stage=0;renderElectrochem();},null,()=>electro.measured&&electro.plateNotes?.trim()?null:'Tee kuparipinnoitus ja kirjaa havaintosi.','plating-v4');}typesetChemicalText();};

ART_TITLES['displacement-setup']='Metallin ja suolaliuoksen reaktio';ART_TITLES['oxide-study']='Oksidien happamuuden tutkiminen';ART_TITLES['buffer-study']='Puskuriliuoksen tutkiminen';ART_TITLES['aluminium-foil']='Alumiinifolio ja lämmönsiirrin';ART_TITLES['stainless-steel']='Ruostumattomat ruokailuvälineet';
const chemicalTextBefore=cleanVisibleText;
cleanVisibleText=function(root=app){chemicalTextBefore(root);const walk=node=>{if(node.nodeType===1){if(node.namespaceURI==='http://www.w3.org/2000/svg'||['INPUT','SELECT','TEXTAREA','SCRIPT','STYLE'].includes(node.tagName.toUpperCase())||node.classList?.contains('katex'))return;for(const c of Array.from(node.childNodes))walk(c);}else if(node.nodeType===3)node.textContent=node.textContent.replace(/syrjäytymisreaktiota/gi,'kemiallista reaktiota').replace(/syrjäytymisreaktion/gi,'kemiallisen reaktion').replace(/syrjäytymisreaktiossa/gi,'kemiallisessa reaktiossa').replace(/syrjäytymisreaktio/gi,'kemiallinen reaktio');};walk(root);};

// Reviewed task structure and native chemical models.
INTRO_TEXT[0].splice(1,0,'<b>Jaksollinen järjestelmä</b> on taulukko, jossa alkuaineet on järjestetty kasvavan järjestysluvun mukaan. Vaakasuorat rivit ovat jaksoja ja pystysuorat sarakkeet ryhmiä. Saman pääryhmän alkuaineilla on samankaltaisia kemiallisia ominaisuuksia.');
INTRO_TEXT[0][4]='<b>Pääryhmät</b> ovat ryhmät 1, 2 ja 13–18. Ryhmässä 1 ovat alkalimetallit (vety on poikkeus), ryhmässä 2 maa-alkalimetallit, ryhmässä 17 halogeenit ja ryhmässä 18 jalokaasut. Pääryhmissä 1 ja 2 atomilla on yksi tai kaksi ulkoelektronia, pääryhmissä 13–18 kolmesta kahdeksaan. Heliumilla on kaksi.';
INTRO_TEXT[0][5]='<b>Kuorten täyttö:</b> Sisimmälle kuorelle mahtuu kaksi elektronia ja toiselle kahdeksan. Ensimmäisten 20 alkuaineen kuorimalleissa kolmannelle kuorelle tulee enintään kahdeksan elektronia, minkä jälkeen aletaan täyttää neljättä. Piirrä toisesta kuoresta alkaen ensin neljä elektronia yksittäin ja täydennä sitten parit.';
INTRO_TEXT[1].push('<b>Ionisidos</b> muodostuu tavallisesti metallin ja epämetallin välille. Metalliatomi luovuttaa elektroneja ja epämetalliatomi vastaanottaa niitä. Syntyneet vastakkaismerkkiset ionit vetävät toisiaan puoleensa. Kaava kertoo ionien pienimmän lukumääräsuhteen.');
INTRO_TEXT[2][1]='<b>Kovalenttinen sidos</b> muodostuu epämetalliatomien välille, kun atomit jakavat yhden tai useamman elektroniparin. Yhteinen pari kuuluu kummankin atomin uloimmalle kuorelle.';
INTRO_TEXT[4]=['Happo ja emäs reagoivat','<b>Neutraloitumisessa</b> happo ja emäs reagoivat keskenään. Esimerkiksi suolahapon ja kaliumhydroksidin reaktiossa syntyy kaliumkloridia ja vettä. Kaliumkloridi on suola.','Vesiliuoksessa oksonium- ja hydroksidi-ionit reagoivat ja muodostavat vettä. Kalium- ja kloridi-ionit jäävät liuokseen.','<b>Titrauksessa</b> emäsliuosta lisätään vähitellen happoliuokseen tai happoliuosta emäsliuokseen. Byretin hanalla voidaan annostella pieniä määriä liuosta.','<b>Ekvivalenttipisteessä</b> happoa ja emästä on lisätty toisiinsa juuri reaktion vaatima määrä. Lähellä tätä pistettä pienikin lisäys voi muuttaa pH:ta huomattavasti.'];
INTRO_TEXT[5].push('<b>Karbonaatit</b> reagoivat happojen kanssa, jolloin vapautuu hiilidioksidia CO2. Hiilidioksidi sammuttaa palavan tulitikun liekin. Tämä havainto ei yksin varmista kaasun tunnistamista. Hiilidioksidi voidaan tunnistaa myös johtamalla sitä kalkkiveteen, joka samenee.');
INTRO_TEXT[6][2]='Kun epäjalompi metalli upotetaan jalomman metallin ioneja sisältävään liuokseen, metalliatomit voivat luovuttaa elektroneja liuoksen ioneille. Epäjalompaa metallia liukenee ja sen pinnalle muodostuu jalompaa metallia.';
INTRO_TEXT[6][3]='<b>Korroosio</b> tarkoittaa metallin syöpymistä sen reagoidessa ympäristön aineiden kanssa. Raudan ruostuminen on korroosiota, joka tarvitsee tavallisissa oloissa vettä ja happea. Terästä voidaan suojata esimerkiksi maalipinnalla tai siihen sähköisesti yhdistetyllä epäjalommalla <b>uhrimetallilla</b>, joka syöpyy teräksen sijasta.';
INTRO_TEXT[7]=['Sähkökemiallinen pari ja elektrolyysi','<b>Sähkökemiallisessa parissa</b> kemiallinen reaktio tuottaa sähköenergiaa. Tässä sähkökemiallisessa parissa molemmat metallilevyt ovat samassa elektrolyyttiliuoksessa.','<b>Elektrolyysissä</b> sähköenergia saa aikaan kemiallisen reaktion. Elektrolyysiä käytetään esimerkiksi metallien valmistamiseen ja esineiden pinnoittamiseen. Myös vettä voidaan hajottaa vedyksi ja hapeksi.','<b>Kuparipinnoituksessa</b> pinnoitettava esine kytketään jännitelähteen miinusnapaan. Sen pinnalla kupari-ionit vastaanottavat elektroneja ja muuttuvat kupariksi.'];
TITLES[5]='Tuntemattomien aineiden tunnistaminen';
pageHead=function(title){if(!page)return `<div class="top"><h1>${esc(title)}</h1></div>`;const tabs=[['intro','Tutustu'],['quiz','Monivalinnat'],['train','Perustehtävät']];if(page===3)tabs.push(['apply','Nimeämisharjoitus']);if([4,5,6,8].includes(page))tabs.push(['lab','Kokeelliset tehtävät']);return `<div class="top"><h1>${esc(title)}</h1></div><nav class="tabs section-tabs" aria-label="Treenin osat">${tabs.map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}">${t}</button>`).join('')}</nav>`;};
const quizBeforeReview=renderQuiz;renderQuiz=function(){quizBeforeReview();const b=app.querySelector('.actions [data-view="train"]');if(b)b.textContent='Perustehtäviin →';};
// Native SVG typography: charge is attached to its ion, not floating at the sphere edge.
ionNode=function(sy,q,x,y,r=28){const base=unicodeChem(sy),sz=sy.length>3?14:20,w=base.length*sz*.55,cx=x-w*.12;return `<g class="ion-node" data-charge="${q}"><circle cx="${x}" cy="${y}" r="${r}" fill="${q>0?'#e1e6eb':'#fff'}" stroke="#657181" stroke-width="1.6"/><text x="${cx}" y="${y+6}" text-anchor="middle" font-family="system-ui" font-size="${sz}" fill="#172033">${esc(base)}<tspan dx="1" dy="-12" font-size="12">${chargeText(q)}</tspan></text></g>`;};
saltSVG=function(t,cp,ap){if(cp+ap===0)return svgStart(560,230,'Ionien lukumääräsuhde')+txt(280,130,'Valitse ionien lukumäärät.',20)+'</svg>';const balanced=cp>0&&ap>0&&cp*t.cq+ap*t.aq===0,repeat=balanced?Math.max(1,Math.min(4,Math.floor(24/(cp+ap)))):1,per=cp+ap,ions=[];for(let k=0;k<repeat;k++){for(let j=0;j<Math.max(cp,ap);j++){if(j<cp)ions.push(true);if(j<ap)ions.push(false);}}const cols=balanced?Math.min(6,per*2):Math.min(6,Math.max(1,per)),rows=Math.ceil(ions.length/cols),gap=Math.min(70,450/cols),left=280-(cols-1)*gap/2,h=rows*70+100;let s=svgStart(560,h,'Kiderakenteen yksinkertaistettu malli');ions.forEach((c,j)=>{let col=j%cols;if(Math.floor(j/cols)%2&&cp===ap)col=cols-1-col;s+=ionNode(c?t.cation:t.anion,c?t.cq:t.aq,left+col*gap,50+Math.floor(j/cols)*70,Math.min(26,gap*.41));});if(balanced){for(let row=0;row<rows;row++)s+=txt(left-gap*.8,56+row*70,'…',22)+txt(560-left+gap*.8,56+row*70,'…',22);s+=txt(280,h-15,'Kiderakenteen yksinkertaistettu malli',17);}return s+'</svg>';};
ionicExampleSVG=function(step=0){if(step===3)return naclCrystalSVG();if(step===2)return saltSVG({cation:'Ca',anion:'Cl',cq:2,aq:-1},1,2);let s=svgStart(560,270,'Kalsiumkloridin muodostuminen');if(step===0){s+=lewisSymbolSVG('Ca',115,127,2)+lewisSymbolSVG('Cl',405,70,7)+lewisSymbolSVG('Cl',405,195,7);s+=line(115,94,372,80,'marker-end="url(#arrow)"')+line(148,127,372,205,'marker-end="url(#arrow)"');s+=txt(280,255,'Kumpikin klooriatomi vastaanottaa yhden elektronin.',15);}else{s+=ionNode('Ca',2,145,132,34)+ionNode('Cl',-1,405,70,34)+ionNode('Cl',-1,405,195,34);for(const y of [70,195]){const dx=405-145,dy=y-132,d=Math.hypot(dx,dy),ux=dx/d,uy=dy/d;const p=[145+ux*40,132+uy*40],q=[405-ux*40,y-uy*40],mx=(p[0]+q[0])/2,my=(p[1]+q[1])/2;s+=line(p[0],p[1],mx-ux*12,my-uy*12,'marker-end="url(#arrow)"')+line(q[0],q[1],mx+ux*12,my+uy*12,'marker-end="url(#arrow)"');}s+=txt(280,255,'Vastakkaismerkkiset ionit vetävät toisiaan puoleensa.',15);}return s+'</svg>';};
// Compress molecules around their centroid. Electron pairs remain attached to bonds.
const moleculeBeforeReview=moleculeSVG;
moleculeSVG=function(m,bonds,lones,style='dots'){const cx=m.a.reduce((n,a)=>n+a[1],0)/m.a.length,cy=m.a.reduce((n,a)=>n+a[2],0)/m.a.length,n={...m,a:m.a.map(a=>[a[0],250+(a[1]-cx)*.58,145+(a[2]-cy)*.58,a[3]])};if(m.formula==='H2O')n.a=[['O',250,120,2],['H',202,157,0],['H',298,157,0]];let s=moleculeBeforeReview(n,bonds,lones,style);s=s.replace(/<text x="([^"]+)" y="([^"]+)" font-size="12" text-anchor="middle">([0-9]+)<\/text>/g,(_,x,y,k)=>`<g class="atom-index" transform="translate(${Number(x)+3} ${Number(y)+10})"><circle r="9" fill="#edf1f4" stroke="#c6cfd6"/><text y="4" font-size="11" text-anchor="middle">${k}</text></g>`);if(m.formula==='H2O'){s=s.replace(/<circle[^>]*class="electron"\/>/g,'');const o=n.a[0];for(let j=0;j<2;j++){if(!(bonds[j]>0))continue;const h=n.a[j+1];s=s.replace('</svg>',dotPair(20+(o[1]+h[1])/2,(o[2]+h[2])/2,Math.atan2(h[2]-o[2],h[1]-o[1])+Math.PI/2)+'</svg>');}for(let j=0;j<(lones[0]||0);j++)s=s.replace('</svg>',dotPair(o[1]+20+(j%2?22:-22),o[2]-27,Math.PI/2)+'</svg>');}return s;};
const introBeforeReview=renderIntro;
renderIntro=function(){introBeforeReview();if(page===1){app.querySelector('.intro-layout').insertAdjacentHTML('afterend',`<section class="panel intro-periodic">${periodicHTML('')}</section>`);bindPeriodic('');}if(page===2)app.querySelector('.charge-equation').insertAdjacentHTML('beforebegin','<p class="charge-principle"><b>Yhdisteessä varausten summa on 0.</b></p>');if(page===3){app.querySelectorAll('.intro-example .atom-index').forEach(g=>g.remove());app.querySelector('.intro-example svg')?.querySelectorAll('text').forEach(t=>{if(/^[123]$/.test(t.textContent))t.remove();});const formula=app.querySelector('.intro-example p:last-of-type');if(formula)formula.className='example-formula';}if(page===7){const p=app.querySelector('.intro-example p');p.innerHTML='Kun rautapala upotetaan kuparisulfaattiliuokseen, rautaa liukenee ja rautapalan pinnalle muodostuu kuparia.';}};
neutralModelSVG=function(){return svgStart(620,290,'Oksonium- ja hydroksidi-ionit reagoivat vedeksi')+ionNode('H3O',1,110,140,39)+txt(205,149,'+',27)+ionNode('OH',-1,280,140,37)+line(337,140,382,140,'marker-end="url(#arrow)"')+waterParticle(445,95)+waterParticle(530,180)+'</svg>';};
